INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('79d03d48-7cff-50de-a127-8f315e6310fe', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 6, 6, 'A 2.5 kg mass hangs from a newton-meter, which reads 24.5 N. Calculate the gravitational field strength at that place.', NULL, 1, 'numeric'::answer_type, '9.8', 'N kg⁻¹', false, NULL, false, NULL, 'g = F/m = 24.5 ÷ 2.5 = 9.80 N kg⁻¹. Mark scheme (1 mark). A1: g = 9.80 N kg⁻¹.', 1, NULL, NULL),
('0346fd3d-26b5-556e-8f82-bec59a8a03c7', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 7, 7, 'The gravitational field strength on the Moon''s surface is 1.62 N kg⁻¹. What is the weight of an 85 kg astronaut standing there?', NULL, 1, 'numeric'::answer_type, '137.7', 'N', false, NULL, false, NULL, 'W = mg = 85 × 1.62 = 138 N. Mark scheme (1 mark). A1: W = 138 N.', 1, NULL, NULL),
('20b67367-04d0-579d-9ad3-a28744bb88fd', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 8, 8, 'A rover weighs 1150 N on the surface of Mars, where the gravitational field strength is 3.71 N kg⁻¹. Calculate the mass of the rover.', NULL, 1, 'numeric'::answer_type, '310', 'kg', false, NULL, false, NULL, 'm = W/g = 1150 ÷ 3.71 = 310 kg. Mark scheme (2 marks). C1: W = mg rearranged. A1: m = 310 kg.', 2, NULL, NULL),
('828d3a22-0953-5e0f-b0fa-88ddb496397c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 9, 9, 'Which unit is a correct unit of gravitational field strength?', NULL, 1, 'multiple_choice'::answer_type, 'N kg⁻¹', NULL, false, NULL, false, NULL, 'g is the force per unit mass, F/m, so its unit is N kg⁻¹ (equivalent to m s⁻²). Mark scheme (1 mark). B1: C (N kg⁻¹).', 1, NULL, NULL),
('ae2d5d61-5e7a-581d-87ea-5e0e7b14872f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 10, 10, 'Which describes the gravitational field lines around an isolated spherical planet?', NULL, 1, 'multiple_choice'::answer_type, 'Radial, pointing inwards towards the centre of the planet', NULL, false, NULL, false, NULL, 'The force on a test mass is always towards the planet''s centre, so the field lines are radial and point inwards. They get further apart with distance, showing g decreasing. Mark scheme (1 mark). B1: A (Radial, pointing inwards towards the centre of the planet).', 1, NULL, NULL),
('5a5c101a-2d2d-50f0-b5e4-2e83dbf6f900', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 11, 11, 'Close to the Earth''s surface, over a region a few kilometres across, the gravitational field is described as uniform. What does this mean?', NULL, 1, 'multiple_choice'::answer_type, 'The field strength has the same size and direction everywhere in the region', NULL, false, NULL, false, NULL, 'Over a small region the field lines are effectively parallel and equally spaced: g has the same magnitude (≈ 9.81 N kg⁻¹) and direction (vertically down) everywhere. Mark scheme (1 mark). B1: D (The field strength has the same size and direction everywhere in the region).', 1, NULL, NULL),
('2317179f-43ff-5f1f-96f9-77af177bc10e', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 12, 12, 'Why is gravitational field strength a vector quantity?', NULL, 1, 'multiple_choice'::answer_type, 'It is a force per unit mass, and force has direction', NULL, false, NULL, false, NULL, 'g = F/m. Force is a vector and mass is a scalar, so g has a direction: the direction of the force on a mass placed in the field. Mark scheme (1 mark). B1: B (It is a force per unit mass, and force has direction).', 1, NULL, NULL),
('f7fbf1fc-f5c3-5eef-bdf3-255515639661', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 13, 13, 'What do the arrows on gravitational field lines show?', NULL, 1, 'multiple_choice'::answer_type, 'The direction of the force on a small mass placed in the field', NULL, false, NULL, false, NULL, 'Field lines show the direction of the gravitational force on a test mass. Their closeness shows the strength of the field. Mark scheme (1 mark). B1: C (The direction of the force on a small mass placed in the field).', 1, NULL, NULL),
('bcce3ecc-5f18-53f3-8d15-240d25debe67', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 14, 14, 'The gravitational field strength at the cloud tops of Jupiter is about 24.8 N kg⁻¹. Calculate the gravitational force on a 0.40 kg probe there.', NULL, 1, 'numeric'::answer_type, '9.92', 'N', false, NULL, false, NULL, 'F = mg = 0.40 × 24.8 = 9.92 N. Mark scheme (1 mark). A1: F = 9.92 N.', 1, NULL, NULL),
('ae1a44c2-63c3-534d-8bab-e85db93ac902', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 15, 15, 'A 70 kg astronaut weighs 687 N on Earth. On Venus she would weigh 621 N. Calculate the gravitational field strength at the surface of Venus.', NULL, 1, 'numeric'::answer_type, '8.871', 'N kg⁻¹', false, NULL, false, NULL, 'g = W/m = 621 ÷ 70 = 8.87 N kg⁻¹. Mark scheme (2 marks). C1: g = W/m. A1: g = 8.87 N kg⁻¹.', 2, NULL, NULL),
('aaf77728-bb0a-5e6d-bccd-8be5b0f00110', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 16, 16, 'A student says "an astronaut on the International Space Station is weightless because there is no gravity in space". Which correction is right?', NULL, 1, 'multiple_choice'::answer_type, 'Gravity at the ISS is about 90% of that on the ground; the astronaut is in free fall around the Earth', NULL, false, NULL, false, NULL, 'At 400 km altitude g ≈ 8.7 N kg⁻¹. Both the station and the astronaut fall towards the Earth with the same acceleration, so nothing pushes on the astronaut and they feel weightless. Mark scheme (1 mark). B1: A (Gravity at the ISS is about 90% of that on the ground; the astronaut is in free fall around the Earth).', 1, NULL, NULL),
('a6c1ea5d-5db6-590c-bd3a-82368f5e7de9', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 17, 17, 'Which statement about a gravitational field is correct?', NULL, 1, 'multiple_choice'::answer_type, 'It is a region in which a mass experiences a force', NULL, false, NULL, false, NULL, 'Any mass creates a gravitational field around it; another mass in that region feels an attractive force. Gravity is never repulsive. Mark scheme (1 mark). B1: D (It is a region in which a mass experiences a force).', 1, NULL, NULL),
('1996a2bd-1f49-5091-9e12-d4641de8f8b3', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 18, 18, 'Field lines are drawn around two planets. Around planet P the lines are drawn twice as close together as around planet Q, at the same distance from each centre. What does this show?', NULL, 1, 'multiple_choice'::answer_type, 'The field strength near P is greater than near Q', NULL, false, NULL, false, NULL, 'The closer the field lines, the stronger the field. At the same distance, a stronger field means a more massive planet. Mark scheme (2 marks). C1: closer lines = stronger field. A1: B (The field strength near P is greater than near Q).', 2, NULL, NULL),
('fb70de19-1373-5c6d-bdab-febdb120ad47', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 19, 19, 'Which statement about the Earth''s gravitational field outside the Earth is correct?', NULL, 1, 'multiple_choice'::answer_type, 'It is radial and its strength decreases with distance from the centre', NULL, false, NULL, false, NULL, 'Outside the Earth the field is radial (towards the centre) with g = GM/r², decreasing with distance. Mark scheme (1 mark). B1: C (It is radial and its strength decreases with distance from the centre).', 1, NULL, NULL),
('1e633017-4811-5daa-a593-0660e65f666f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 20, 20, 'For a uniform spherical planet, g at the surface is proportional to its density × its radius. Planet K has half the Earth''s density and twice the Earth''s radius. Calculate g at the surface of K. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '9.81', 'N kg⁻¹', false, NULL, false, NULL, 'g = GM/R² with M = (4/3)πR³ρ gives g = (4/3)πGρR, so g ∝ ρR. g_K = 9.81 × 0.5 × 2.0 = 9.81 N kg⁻¹. Mark scheme (3 marks). C1: g ∝ ρR (from g = GM/R² and M = ⁴⁄₃πR³ρ). C1: factors 0.5 and 2.0. A1: g_K = 9.81 N kg⁻¹. Common mistake: using g ∝ M/R² with M unchanged.', 3, NULL, NULL),
('d44ed560-ad5c-59f5-a7e3-012b12dfadb2', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 21, 21, 'A planet has 4.0 times the mass of the Earth and 2.0 times its radius. Calculate the gravitational field strength at its surface. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '9.81', 'N kg⁻¹', false, NULL, false, NULL, 'g = GM/R² ∝ M/R². g = 9.81 × 4.0 ÷ 2.0² = 9.81 N kg⁻¹. Mark scheme (3 marks). C1: g ∝ M/R². C1: substitution of factors. A1: g = 9.81 N kg⁻¹.', 3, NULL, NULL),
('1e8fdcbb-ea65-5656-be8c-b56b72a35466', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 22, 22, 'A pendulum clock is moved from the Earth to a planet where it swings with a period 1.20 times as long. The period of a pendulum is proportional to 1/√g. Calculate g on the planet. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '6.813', 'N kg⁻¹', false, NULL, false, NULL, 'T ∝ 1/√g, so g ∝ 1/T². g = 9.81 ÷ 1.20² = 6.81 N kg⁻¹. Mark scheme (3 marks). C1: g ∝ 1/T². C1: substitution. A1: g = 6.81 N kg⁻¹.', 3, NULL, NULL),
('a70a07df-3a79-5b2b-9c9a-a517d9768d85', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 23, 23, 'A uniform gravitational field is shown by field lines. Which pattern represents it?', NULL, 2, 'multiple_choice'::answer_type, 'Parallel, equally spaced lines with arrows all pointing the same way', NULL, false, NULL, false, NULL, 'A uniform field has the same strength and direction everywhere: parallel lines (same direction) equally spaced (same strength). Mark scheme (3 marks). C1: parallel = same direction. C1: equal spacing = same strength. A1: C (Parallel, equally spaced lines with arrows all pointing the same way).', 3, NULL, NULL),
('505031cb-40c6-568d-9fe6-1111aba65565', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 24, 24, 'Two stars P and Q of equal mass are a distance d apart. Where is the resultant gravitational field strength due to the two stars zero?', NULL, 2, 'multiple_choice'::answer_type, 'At the midpoint of the line joining them', NULL, false, NULL, false, NULL, 'At the midpoint the two fields are equal in size and opposite in direction, so they cancel. Elsewhere on the perpendicular bisector the fields have components that add towards the line PQ. Mark scheme (3 marks). C1: fields are vectors in opposite directions between the stars. C1: equal masses, equal distances: midpoint. A1: A (At the midpoint of the line joining them).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 160" role="img" aria-labelledby="fg0085fd67-t fg0085fd67-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg0085fd67-t">Two equal stars</title><desc id="fg0085fd67-d">Two stars P and Q of equal mass a distance d apart.</desc><polygon points="70,108 76.3,105 76.3,111" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="108" x2="345.1" y2="108" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="350,108 343.7,111 343.7,105" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="210" y="120" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">d</text><circle cx="70" cy="52" r="16" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">P</text><circle cx="350" cy="52" r="16" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="350" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Q</text></svg>', 'Two stars P and Q of equal mass a distance d apart.'),
('130e7241-d888-567f-89e2-810ae1124d5c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 25, 25, 'At a point X, the Earth''s gravitational field strength is 2.5 N kg⁻¹ towards the Earth and the Moon''s is 0.40 N kg⁻¹ towards the Moon, in the opposite direction. Which is the resultant field at X?', NULL, 2, 'multiple_choice'::answer_type, '2.1 N kg⁻¹ towards the Earth', NULL, false, NULL, false, NULL, 'The fields are vectors in opposite directions. Resultant = 2.5 − 0.40 = 2.1 N kg⁻¹, in the direction of the larger one (towards the Earth). Mark scheme (4 marks). C1: fields are vectors. C1: opposite directions so subtract. C1: direction of larger field. A1: D (2.1 N kg⁻¹ towards the Earth).', 4, NULL, NULL),
('b0c979d5-3535-5562-ae53-517a215114bc', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 26, 26, 'At a point P, the gravitational field of planet A is 3.0 N kg⁻¹ due north and the field of planet B is 4.0 N kg⁻¹ due east. Calculate the magnitude of the resultant gravitational field strength at P.', NULL, 2, 'numeric'::answer_type, '5', 'N kg⁻¹', false, NULL, false, NULL, 'The fields are at right angles, so g = √(3.0² + 4.0²) = 5.0 N kg⁻¹ (at tan⁻¹(4/3) = 53° east of north). Mark scheme (3 marks). C1: vector addition. C1: Pythagoras. A1: g = 5.0 N kg⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 230" role="img" aria-labelledby="fg94847973-t fg94847973-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg94847973-t">Two fields at P</title><desc id="fg94847973-d">Vector diagram at P (north up the page): planet A gives 3.0 N kg⁻¹ due north and planet B gives 4.0 N kg⁻¹ due east.</desc><line x1="70" y1="180" x2="70" y2="81.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="70,75 73.8,83.2 66.2,83.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="70" y="61" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">3.0 N kg⁻¹ north (A)</text><line x1="70" y1="180" x2="203.7" y2="180" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="210,180 201.8,183.8 201.8,176.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="224" y="180" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 N kg⁻¹ east (B)</text><circle cx="70" cy="180" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Vector diagram at P (north up the page): planet A gives 3.0 N kg⁻¹ due north and planet B gives 4.0 N kg⁻¹ due east.'),
('b4cc9586-2cab-5687-b220-514278ee936b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 27, 27, 'A 0.060 kg hammer is dropped by an astronaut on Mars and accelerates at 3.7 m s⁻² (no atmosphere effects). Calculate (a) the gravitational field strength and (b) the gravitational force on the hammer. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '0.222', 'N', false, NULL, false, NULL, '(a) In free fall the acceleration equals the field strength: g = 3.7 N kg⁻¹. (b) F = mg = 0.060 × 3.7 = 0.222 N. Mark scheme (3 marks). B1: g = free-fall acceleration. C1: F = mg. A1: F = 0.222 N.', 3, NULL, NULL),
('b65653fd-44df-5413-92d3-0365eebd2b4c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 28, 28, 'Why can gravitational field strength be given in m s⁻² as well as in N kg⁻¹?', NULL, 2, 'multiple_choice'::answer_type, 'Because a mass in free fall accelerates at g, and 1 N kg⁻¹ = 1 m s⁻²', NULL, false, NULL, false, NULL, 'F = mg and F = ma for free fall, so a = g. 1 N = 1 kg m s⁻², so 1 N kg⁻¹ = 1 m s⁻². Mark scheme (3 marks). C1: free-fall acceleration = g. C1: unit equivalence. A1: B (Because a mass in free fall accelerates at g, and 1 N kg⁻¹ = 1 m s⁻²).', 3, NULL, NULL),
('7f38cce0-9feb-5e6d-8e11-6d70a4bf92f5', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 29, 29, 'A 5.0 kg mass is weighed at the Equator, where g = 9.79 N kg⁻¹, and at the North Pole, where g = 9.83 N kg⁻¹. Calculate the difference in its weight.', NULL, 2, 'numeric'::answer_type, '0.2', 'N', false, NULL, false, NULL, 'W = mg. Difference = m Δg = 5.0 × (9.83 − 9.79) = 0.20 N. Mark scheme (3 marks). C1: W = mg at each place. C1: difference. A1: ΔW = 0.20 N.', 3, NULL, NULL),
('32f79952-aec3-512c-8838-fc370c4f1d97', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 30, 30, 'A spherical planet has field lines drawn on a diagram. A student draws the lines at twice the distance from the centre four times further apart in area. What does this represent?', NULL, 2, 'multiple_choice'::answer_type, 'g falls to one quarter when the distance from the centre doubles', NULL, false, NULL, false, NULL, 'The same number of radial lines passes through a sphere of area 4πr². Doubling r gives 4 times the area, so the line density, and g, falls to one quarter: g ∝ 1/r². Mark scheme (3 marks). C1: line density ∝ 1/r². C1: g quartered. A1: C (g falls to one quarter when the distance from the centre doubles).', 3, NULL, NULL),
('6c16708f-bcb4-577a-b9aa-6656c02eb1a7', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 31, 31, 'An astronaut drops a feather and a hammer together on the Moon (g = 1.62 N kg⁻¹) from a height of 1.5 m. Calculate the time they take to reach the ground and explain why they land together.', NULL, 2, 'numeric'::answer_type, '1.361', 's', false, NULL, false, NULL, 'There is no air resistance, so both accelerate at g. s = ½gt², t = √(2s/g) = √(2 × 1.5 ÷ 1.62) = 1.36 s. The acceleration does not depend on mass, so they land together. Mark scheme (4 marks). B1: acceleration = g, independent of mass. C1: s = ½gt². C1: rearranged for t. A1: t = 1.36 s.', 4, NULL, NULL),
('1ae529d0-29bd-506b-a41e-f95fb59244b4', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 32, 32, 'A planet''s radius is 0.53 times the Earth''s and its surface field strength is 3.7 N kg⁻¹. By what factor is its mass smaller than the Earth''s? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '9.439', NULL, false, NULL, false, NULL, 'M = gR²/G, so M_planet/M_Earth = (3.7 ÷ 9.81) × 0.53² = 0.106. The planet is smaller by a factor of 1 ÷ 0.1059 = 9.44. Mark scheme (3 marks). C1: M ∝ gR². C1: ratio of g and square of radius ratio. A1: factor = 9.44.', 3, NULL, NULL),
('86f4b5ed-96ba-5508-a264-d0feef9e8acc', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 33, 33, 'The field strength at the Earth''s surface is 9.81 N kg⁻¹. Which change would NOT change the field strength at the surface?', NULL, 2, 'multiple_choice'::answer_type, 'Doubling the mass of a person standing there', NULL, false, NULL, false, NULL, 'g is a property of the field (GM/r²), not of the test mass. Changing the Earth''s mass or radius, or the distance from the centre, all change g. Mark scheme (3 marks). C1: g = GM/r². C1: independent of test mass. A1: A (Doubling the mass of a person standing there).', 3, NULL, NULL),
('e1dc0ed5-db56-5dd0-a833-1554926cb352', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 34, 34, 'A space probe hovers at a point where its weight is 52 N. At the Earth''s surface the same probe weighs 470 N. How many Earth radii from the Earth''s centre is the probe?', NULL, 2, 'numeric'::answer_type, '3.006', NULL, false, NULL, false, NULL, 'W ∝ 1/r². r/R = √(470 ÷ 52) = 3.01 Earth radii. Mark scheme (4 marks). C1: W ∝ g ∝ 1/r². C1: ratio of weights. C1: square root. A1: r/R = 3.01.', 4, NULL, NULL),
('fd56946a-53d9-5b3f-8c78-8e8079dbbbee', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 35, 35, 'A test mass is moved from the surface of a planet to a point one planet-radius above the surface. What happens to the gravitational force on it?', NULL, 2, 'multiple_choice'::answer_type, 'It falls to one quarter', NULL, false, NULL, false, NULL, 'One radius above the surface is a distance 2R from the centre. F ∝ 1/r², so F falls by a factor of 2² = 4. Mark scheme (3 marks). C1: distance from centre = 2R. C1: inverse square. A1: D (It falls to one quarter). Common mistake: taking the distance as R instead of 2R and answering "it halves".', 3, NULL, NULL),
('bb3943ab-fc1a-531a-ae2e-4a111a11cdac', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 36, 36, 'Near the surface of a planet, a 2.0 kg ball takes 1.10 s to fall from rest through 3.0 m in a vacuum chamber. Calculate the gravitational field strength there.', NULL, 2, 'numeric'::answer_type, '4.959', 'N kg⁻¹', false, NULL, false, NULL, 's = ½gt², so g = 2s/t² = 2 × 3.0 ÷ 1.10² = 4.96 N kg⁻¹. Mark scheme (3 marks). C1: s = ½gt². C1: rearranged for g. A1: g = 4.96 N kg⁻¹.', 3, NULL, NULL),
('4488921b-6fbc-579b-83cf-ff3a91aa1a5d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 37, 37, 'A spring balance is calibrated on Earth (g = 9.81 N kg⁻¹) to show mass in kg. On a moon it reads 0.35 kg for an object whose true mass is 2.0 kg. Calculate the gravitational field strength on the moon.', NULL, 2, 'numeric'::answer_type, '1.717', 'N kg⁻¹', false, NULL, false, NULL, 'The balance measures force: reading × 9.81 = weight. Weight = 0.35 × 9.81 = 3.43 N, so g = weight ÷ true mass = 3.43 ÷ 2.0 = 1.72 N kg⁻¹. Mark scheme (3 marks). C1: balance reads force/9.81. C1: weight = reading × 9.81. C1: g = W/m.', 3, NULL, NULL),
('8f6bad0e-14de-5bcc-a601-77ca7f9eeb51', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 38, 38, 'A uniform gravitational field acts vertically downwards. A ball is thrown horizontally in it. Which describes the force on the ball during its flight (no air resistance)?', NULL, 2, 'multiple_choice'::answer_type, 'Constant in size and direction, vertically downwards', NULL, false, NULL, false, NULL, 'In a uniform field g is the same everywhere, so F = mg is constant and always vertically down — this gives the parabolic path. Mark scheme (3 marks). C1: uniform field: same g everywhere. C1: direction downwards. A1: B (Constant in size and direction, vertically downwards).', 3, NULL, NULL),
('8f602245-f386-5937-88c2-1ccb4f81ea5a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 39, 39, 'A planet has the same density as the Earth but twice its radius. Calculate the gravitational field strength at its surface. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '19.62', 'N kg⁻¹', false, NULL, false, NULL, 'g = (4/3)πGρR, so with the same ρ, g ∝ R. g = 2 × 9.81 = 19.6 N kg⁻¹. Mark scheme (3 marks). C1: M ∝ ρR³. C1: g ∝ M/R² ∝ ρR. A1: g = 19.6 N kg⁻¹.', 3, NULL, NULL),
('7e69b876-342e-5224-ab0d-5861715f3eb5', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 40, 40, 'Planet X has radius 3.4 × 10⁶ m. A probe of mass 120 kg on its surface weighs 445 N. (a) Calculate g at the surface. (b) Calculate the mass of planet X. (c) Calculate its mean density. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '6.427e23', 'kg', false, NULL, false, NULL, '(a) g = W/m = 445 ÷ 120 = 3.71 N kg⁻¹. (b) g = GM/R², M = gR²/G = 3.71 × (3.4 × 10⁶)² ÷ 6.67 × 10⁻¹¹ = 6.43 × 10²³ kg. (c) ρ = M/(⁴⁄₃πR³) = 3900 kg m⁻³. Mark scheme (5 marks). C1: g = W/m. A1: g. C1: M = gR²/G. A1: M = 6.43 × 10²³ kg. B1: density with V = ⁴⁄₃πR³.', 5, NULL, NULL),
('9c51f0bc-4bdc-5dc4-9963-7f02b631455e', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 41, 41, 'A GPS satellite orbits at 2.0 × 10⁷ m above the Earth''s surface. (a) Calculate its distance from the Earth''s centre. (b) Calculate the gravitational field strength there. (c) Explain why the field lines around the Earth would be drawn much further apart at this distance than near the surface. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '0.5726', 'N kg⁻¹', false, NULL, false, NULL, '(a) r = 6.37 × 10⁶ + 2.0 × 10⁷ = 2.64 × 10⁷ m. (b) g = GM/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ (2.637 × 10⁷)² = 0.573 N kg⁻¹. (c) The field is much weaker (g ∝ 1/r²): the same number of lines spreads over a much larger sphere, so they are further apart. Mark scheme (5 marks). C1: r = R + h. C1: g = GM/r². A1: g = 0.573 N kg⁻¹. B1: weaker field. B1: line spacing shows strength.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fge1cc2e90-t fge1cc2e90-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge1cc2e90-t">GPS satellite orbit</title><desc id="fge1cc2e90-d">The Earth (radius 6.37 × 10⁶ m) and the circular orbit of a GPS satellite 2.0 × 10⁷ m above the surface, drawn to scale.</desc><circle cx="180" cy="160" r="30.4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="180" y="160" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><circle cx="180" cy="160" r="126" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="174" y="30" width="12" height="8" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,129.6 177,123.2 183,123.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="180" y1="124.7" x2="180" y2="43.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,39 183,45.3 177,45.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="188" y="86.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">2.0 × 10⁷ m</text></svg>', 'The Earth (radius 6.37 × 10⁶ m) and the circular orbit of a GPS satellite 2.0 × 10⁷ m above the surface, drawn to scale.'),
('f2b2b701-eb3b-567a-93c0-33c9e632fd0f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 42, 42, 'A spacecraft travels from the Earth (mass 5.97 × 10²⁴ kg) to the Moon (mass 7.35 × 10²² kg). The centres are 3.84 × 10⁸ m apart. (a) Explain why there is a point between them where the resultant gravitational field is zero. (b) Show that at that point (distance x from the Earth''s centre) x/(d − x) = √(M_E/M_M). (c) Calculate x. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3.456e8', 'm', false, NULL, false, NULL, '(a) Between them the Earth''s field points towards the Earth and the Moon''s towards the Moon; somewhere they are equal in size and cancel. (b) GM_E/x² = GM_M/(d − x)², so x²/(d − x)² = M_E/M_M and x/(d − x) = √(M_E/M_M). (c) √(5.97 × 10²⁴ ÷ 7.35 × 10²²) = 9.01, so x = 3.84 × 10⁸ ÷ (1 + 1 ÷ 9.012) = 3.46 × 10⁸ m. Mark scheme (6 marks). B1: opposite directions between them. M1: GM_E/x² = GM_M/(d − x)². M1: square root of both sides. C1: ratio value. C1: rearranged for x. A1: x = 3.46 × 10⁸ m.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 159.8" role="img" aria-labelledby="fg3e359097-t fg3e359097-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3e359097-t">Earth and Moon</title><desc id="fg3e359097-d">The Earth (5.97 × 10²⁴ kg) and the Moon (7.35 × 10²² kg) with centres 3.84 × 10⁸ m apart; somewhere between them the resultant field is zero.</desc><polygon points="70,101.8 76.3,98.8 76.3,104.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="101.8" x2="345.1" y2="101.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="350,101.8 343.7,104.7 343.7,98.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="210" y="113.8" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.84 × 10⁸ m</text><circle cx="70" cy="58" r="22" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Earth</text><circle cx="350" cy="58" r="8" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="350" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Moon</text></svg>', 'The Earth (5.97 × 10²⁴ kg) and the Moon (7.35 × 10²² kg) with centres 3.84 × 10⁸ m apart; somewhere between them the resultant field is zero.'),
('80b35d54-ee65-5a3f-a9fb-b94f25226c09', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 43, 43, 'A table gives the gravitational field strength g at distances r from the centre of a planet, in units of the planet''s radius R: r = 1.0R, g = 9.8 N kg⁻¹; r = 2.0R, g = 2.45 N kg⁻¹; r = 3.0R, g = 1.09 N kg⁻¹; r = 4.0R, g = 0.61 N kg⁻¹. (a) Show that the data fit g ∝ 1/r². (b) Describe the graph of g against 1/r². (c) Predict g at r = 5.0R. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.392', 'N kg⁻¹', false, NULL, false, NULL, '(a) g × r² is constant: 9.8 × 1.0² = 9.8, 2.45 × 2.0² = 9.8, 1.09 × 3.0² = 9.81, 0.61 × 4.0² = 9.76. (b) A straight line through the origin with gradient 9.8 N kg⁻¹ (in units of R²). (c) g = 9.8 ÷ 5.0² = 0.392 N kg⁻¹. Mark scheme (6 marks). M1: gr² calculated for at least three points. A1: constant, so inverse square. B1: straight line through origin. C1: g = 9.8/25. A1: g. A1: g = 0.392 N kg⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 410" role="img" aria-labelledby="fg93a36ec6-t fg93a36ec6-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg93a36ec6-t">Field strength against distance</title><desc id="fg93a36ec6-d">Table and graph of g against distance from the centre of a planet, in planet radii R: g = 9.8 N kg⁻¹ at 1.0R, 2.45 at 2.0R, 1.09 at 3.0R and so on, falling steeply.</desc><g transform="translate(0,0)"><rect x="127.1" y="8" width="145.7" height="140" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="127.1" y="8" width="145.7" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="155.8" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">r / R</text><text x="228.7" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">g / N kg⁻¹</text><line x1="184.5" y1="8" x2="184.5" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="127.1" y1="36" x2="272.9" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="155.8" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0</text><text x="228.7" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">9.8</text><line x1="127.1" y1="64" x2="272.9" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="155.8" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0</text><text x="228.7" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.45</text><line x1="127.1" y1="92" x2="272.9" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="155.8" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0</text><text x="228.7" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.09</text><line x1="127.1" y1="120" x2="272.9" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="155.8" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0</text><text x="228.7" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.61</text></g><g transform="translate(0,160)"><line x1="29.4" y1="34" x2="29.4" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="107.8" y1="34" x2="107.8" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="186.1" y1="34" x2="186.1" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="264.5" y1="34" x2="264.5" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="342.8" y1="34" x2="342.8" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="202" x2="382" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="171.5" x2="382" y2="171.5" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="140.9" x2="382" y2="140.9" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="110.4" x2="382" y2="110.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="79.8" x2="382" y2="79.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="49.3" x2="382" y2="49.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="202" x2="388" y2="202" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="202" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,202 385.7,205 385.7,199" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="202" x2="29.4" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="107.8" y1="202" x2="107.8" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="107.8" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="186.1" y1="202" x2="186.1" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="186.1" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="264.5" y1="202" x2="264.5" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="264.5" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="342.8" y1="202" x2="342.8" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="342.8" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="25.4" y1="202" x2="29.4" y2="202" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="202" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="171.5" x2="29.4" y2="171.5" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="171.5" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="25.4" y1="140.9" x2="29.4" y2="140.9" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="140.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="25.4" y1="110.4" x2="29.4" y2="110.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="110.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">6</text><line x1="25.4" y1="79.8" x2="29.4" y2="79.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="79.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">8</text><line x1="25.4" y1="49.3" x2="29.4" y2="49.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="49.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><text x="205.7" y="234" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r / R</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">g / N kg⁻¹</text><line x1="103.8" y1="48.3" x2="111.8" y2="56.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="103.8" y1="56.3" x2="111.8" y2="48.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="182.1" y1="160.6" x2="190.1" y2="168.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="182.1" y1="168.6" x2="190.1" y2="160.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="260.5" y1="181.4" x2="268.5" y2="189.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="260.5" y1="189.4" x2="268.5" y2="181.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="338.8" y1="188.7" x2="346.8" y2="196.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="338.8" y1="196.7" x2="346.8" y2="188.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></g></svg>', 'Table and graph of g against distance from the centre of a planet, in planet radii R: g = 9.8 N kg⁻¹ at 1.0R, 2.45 at 2.0R, 1.09 at 3.0R and so on, falling steeply.'),
('397df5a9-0886-5168-a7c1-122b2b6a1678', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 44, 44, 'A student models the Earth as a uniform sphere and argues that g inside it, at a distance r from the centre, is proportional to r. (a) Using the model, calculate g at a depth of 1000 km. (b) Calculate g at a height of 1000 km above the surface. (c) State which is larger and explain. Give only the answer to (b). Take g = 9.81 m s⁻². The Earth''s radius is 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '7.328', 'N kg⁻¹', false, NULL, false, NULL, '(a) g ∝ r inside: g = 9.81 × 5.37 × 10⁶ ÷ 6.37 × 10⁶ = 8.27 N kg⁻¹. (b) Outside g ∝ 1/r²: g = 9.81 × (6.37 × 10⁶ ÷ 7.37 × 10⁶)² = 7.33 N kg⁻¹. (c) Inside it is larger here: g falls linearly inside but as 1/r² outside, which falls faster at first. Mark scheme (5 marks). C1: inside: g ∝ r. A1: g at depth. C1: outside: g ∝ 1/r². A1: g = 7.33 N kg⁻¹. B1: comparison.', 5, NULL, NULL),
('09cc59f3-d7e6-52a4-8c01-d2459739a02b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 45, 45, 'Two identical stars, each of mass 2.0 × 10³⁰ kg, are 4.0 × 10¹¹ m apart. Point P is on the perpendicular bisector of the line joining them, 1.5 × 10¹¹ m from the midpoint. (a) Calculate the distance from P to each star. (b) Calculate the field strength at P due to one star. (c) Calculate the resultant field strength at P and state its direction. Give only the size of the resultant in (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '0.002561', 'N kg⁻¹', false, NULL, false, NULL, '(a) √((2.0 × 10¹¹)² + (1.5 × 10¹¹)²) = 2.5 × 10¹¹ m. (b) g = GM/r² = 6.67 × 10⁻¹¹ × 2.0 × 10³⁰ ÷ (2.5 × 10¹¹)² = 0.00213 N kg⁻¹. (c) The components along the line joining the stars cancel; the components towards the midpoint add: 2 × 0.002134 × 1.5 ÷ 2.5 = 0.00256 N kg⁻¹, towards the midpoint. Mark scheme (6 marks). C1: Pythagoras: 2.5 × 10¹¹ m. C1: g = GM/r². A1: g from one star. M1: parallel components cancel. M1: perpendicular components add (× cos θ). A1: g = 0.00256 N kg⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 247" role="img" aria-labelledby="fg86a08795-t fg86a08795-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg86a08795-t">Two stars and a point P</title><desc id="fg86a08795-d">Two identical stars of mass 2.0 × 10³⁰ kg, 4.0 × 10¹¹ m apart. Point P lies on the perpendicular bisector of the line joining them, 1.5 × 10¹¹ m from the midpoint.</desc><polygon points="70,197 76.3,194 76.3,200" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="197" x2="345.1" y2="197" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="350,197 343.7,200 343.7,194" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="210" y="209" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 × 10¹¹ m</text><polygon points="227.5,155 224.5,148.7 230.5,148.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="227.5" y1="150.1" x2="227.5" y2="54.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="227.5,50 230.5,56.3 224.5,56.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="233.5" y="102.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">1.5 × 10¹¹ m</text><circle cx="70" cy="155" r="14" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="129" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">star</text><circle cx="350" cy="155" r="14" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="350" y="129" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">star</text><circle cx="210" cy="50" r="3.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="218" y="38" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">P</text></svg>', 'Two identical stars of mass 2.0 × 10³⁰ kg, 4.0 × 10¹¹ m apart. Point P lies on the perpendicular bisector of the line joining them, 1.5 × 10¹¹ m from the midpoint.'),
('d195a518-53df-53f8-a52b-6ffd3a4f6dcd', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 46, 46, 'A small, dense asteroid has mass 4.5 × 10¹⁵ kg and radius 1.2 km. (a) Calculate the gravitational field strength at its surface. (b) An astronaut of mass 90 kg (with suit) stands on it. Calculate the astronaut''s weight. (c) Suggest why the astronaut must move very carefully. Give only the answer to (a). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '0.2084', 'N kg⁻¹', false, NULL, false, NULL, '(a) g = GM/R² = 6.67 × 10⁻¹¹ × 4.5 × 10¹⁵ ÷ 1200² = 0.208 N kg⁻¹. (b) W = mg = 90 × 0.208 = 18.8 N. (c) The weight is tiny, so even a small jump could reach a speed large enough to leave the asteroid (or take a very long time to come down). Mark scheme (5 marks). C1: g = GM/R² with R in m. A1: g. C1: W = mg. A1: g = 0.208 N kg⁻¹. B1: small weight / easy to escape.', 5, NULL, NULL),
('2640b020-8bfb-5c1e-a749-3a0ab59826e4', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 47, 47, 'A climber stands on the summit of Mount Everest, 8.85 km above sea level. (a) Calculate g at the summit. (b) Calculate the percentage decrease from the sea-level value of 9.82 N kg⁻¹ given by the same model. (c) Explain why a climber does not notice this change. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '0.2773', '%', false, NULL, false, NULL, '(a) g = GM/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ (6.37885 × 10⁶)² = 9.79 N kg⁻¹. (b) g ∝ 1/r², so the fraction remaining is (6.37 ÷ 6.37885)² = 0.99723. Percentage decrease = (1 − 0.99723) × 100 = 0.277 %. (c) 0.3 % is far too small to feel; weight changes by about 2 N for a 70 kg person. Mark scheme (5 marks). C1: r = R + h. A1: g at summit. C1: ratio (R/r)². A1: decrease = 0.277%. B1: change too small to notice.', 5, NULL, NULL),
('9189f2f6-a9b1-55f5-bcb2-f72fe349c145', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 48, 48, 'In a thought experiment, a tunnel is drilled straight through a uniform Earth, and a ball dropped into it. Inside a uniform sphere, g ∝ r. (a) Show that the ball''s acceleration is a = −(g₀/R)x, where x is its distance from the centre and g₀ = 9.81 N kg⁻¹. (b) State what kind of motion this is. (c) Calculate the time for the ball to reach the far side. Earth''s radius = 6.37 × 10⁶ m. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2532', 's', false, NULL, false, NULL, '(a) At distance x from the centre, g = g₀x/R towards the centre, so a = −(g₀/R)x. (b) Acceleration ∝ −displacement: simple harmonic motion. (c) ω = √(g₀/R), T = 2π√(R/g₀). The far side is half a period away: t = π × √(6.37 × 10⁶ ÷ 9.81) = 2530 s (about 42 minutes). Mark scheme (6 marks). M1: g = g₀x/R. A1: a = −(g₀/R)x. B1: s.h.m. C1: T = 2π√(R/g₀). C1: half a period. A1: t = 2530 s.', 6, NULL, NULL),
('4dee8712-f4e2-5158-a86f-3461cae4b130', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 49, 49, 'The table compares two moons. Moon A: mass 1.5 × 10²³ kg, radius 2.6 × 10⁶ m. Moon B: mass 4.8 × 10²² kg, radius 1.6 × 10⁶ m. (a) Calculate g at the surface of each moon. (b) Deduce which moon a lander would need a stronger braking rocket for, explaining your choice. Give only g for moon B. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '1.251', 'N kg⁻¹', false, NULL, false, NULL, '(a) g_A = 6.67 × 10⁻¹¹ × 1.5 × 10²³ ÷ (2.6 × 10⁶)² = 1.48 N kg⁻¹. g_B = 6.67 × 10⁻¹¹ × 4.8 × 10²² ÷ (1.6 × 10⁶)² = 1.25 N kg⁻¹. (b) Moon A, because its surface field (and the lander''s weight to be balanced) is larger. Mark scheme (5 marks). C1: g = GM/R². A1: g_A. A1: g_B = 1.25 N kg⁻¹. B1: compares. B1: braking force must exceed weight.', 5, NULL, NULL),
('de40ebd2-23b0-5fb2-aa47-d15d1421ff64', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 50, 50, 'An astronaut on an unknown planet drops a hammer from rest at a height of 1.80 m and times its fall as 0.85 s (no atmosphere). The planet''s radius is 4.6 × 10⁶ m. (a) Calculate g on the planet. (b) Calculate the planet''s mass. (c) Compare g with the Earth''s value and state one effect on the astronaut. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '1.581e24', 'kg', false, NULL, false, NULL, '(a) g = 2s/t² = 2 × 1.80 ÷ 0.85² = 4.98 N kg⁻¹. (b) M = gR²/G = 4.98 × (4.6 × 10⁶)² ÷ 6.67 × 10⁻¹¹ = 1.58 × 10²⁴ kg. (c) About half of Earth''s g, so the astronaut weighs about half as much and can jump higher. Mark scheme (5 marks). C1: s = ½gt². A1: g. C1: M = gR²/G. A1: M = 1.58 × 10²⁴ kg. B1: comparison and effect.', 5, NULL, NULL),
('fea19aa6-9c5d-5ecd-a6dd-63630b30c354', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '17.1', '9702 coursebook 17.1 · Gravitational fields and field lines', 51, 51, 'A gravimeter (a very sensitive device for measuring g) reads 9.80 N kg⁻¹ at sea level and 9.79 N kg⁻¹ at the top of a tall building, at the same location. (a) Explain why g is smaller at the top. (b) Use g ∝ 1/r² to estimate the height of the building. Take R = 6.37 × 10⁶ m. (c) Suggest why the reading also depends on the rock under the gravimeter. Give only the height in (b).', NULL, 3, 'numeric'::answer_type, '3252', 'm', false, NULL, false, NULL, '(a) It is further from the Earth''s centre. (b) r/R = √(9.80 ÷ 9.79) = 1.00051, so h = 6.37 × 10⁶ × (1.00051 − 1) = 3250 m. (c) Dense rock (or ore) nearby adds a little to the field; low-density rock reduces it. Mark scheme (6 marks). B1: further from centre. C1: r/R = √(g₀/g). M1: h = R(r/R − 1). A1: h = 3300 m. B1: local density variations. B1: denser rock larger g.', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('555ef7af-2905-528d-9c92-12e437840ce3', '828d3a22-0953-5e0f-b0fa-88ddb496397c', 'kg N⁻¹', 'A', false, 0),
('ed820537-d6fe-5d5e-b3f6-5e5172875e84', '828d3a22-0953-5e0f-b0fa-88ddb496397c', 'N m⁻²', 'B', false, 1),
