INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('3af89d54-53b5-5d3a-91ee-e8063c6df722', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 10, 10, 'Two cars of mass 1200 kg and 1500 kg are parked with their centres of mass 3.0 m apart. Treating them as point masses, calculate the gravitational force between them. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '1.334e-5', 'N', false, NULL, false, NULL, 'F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 1200 × 1500 ÷ 3.0² = 1.33 × 10⁻⁵ N. Mark scheme (2 marks). C1: F = Gm₁m₂/r². A1: F = 1.33 × 10⁻⁵ N.', 2, NULL, NULL),
('6af38cc2-6e3f-5ff5-9dc3-a4e6391b841d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 11, 11, 'Calculate the gravitational force between the Earth (5.97 × 10²⁴ kg) and the Sun (1.99 × 10³⁰ kg), whose centres are 1.50 × 10¹¹ m apart. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '3.522e22', 'N', false, NULL, false, NULL, 'F = GMm/r² = 6.67 × 10⁻¹¹ × 1.99 × 10³⁰ × 5.97 × 10²⁴ ÷ (1.50 × 10¹¹)² = 3.52 × 10²² N. Mark scheme (2 marks). C1: Newton''s law of gravitation. A1: F = 3.52 × 10²² N.', 2, NULL, NULL),
('6218d6b4-a038-5eba-8b40-c5dd1c59189d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 12, 12, 'A probe descending into Jupiter''s atmosphere reaches the cloud tops, 7.0 × 10⁷ m from the planet''s centre. Jupiter''s mass is 1.90 × 10²⁷ kg. What gravitational field strength does the probe measure there? Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '25.86', 'N kg⁻¹', false, NULL, false, NULL, 'g = GM/R² = 6.67 × 10⁻¹¹ × 1.90 × 10²⁷ ÷ (7.0 × 10⁷)² = 26 N kg⁻¹. Mark scheme (2 marks). C1: g = GM/R². A1: g = 26 N kg⁻¹.', 2, NULL, NULL),
('57c3892c-803d-5007-9476-1ac2ed0722fe', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 13, 13, 'Newton''s law of gravitation states that the force between two point masses is…', NULL, 1, 'multiple_choice'::answer_type, 'proportional to the product of the masses and inversely proportional to the square of their separation', NULL, false, NULL, false, NULL, 'F = Gm₁m₂/r². Doubling either mass doubles F; doubling r reduces F to a quarter. Mark scheme (1 mark). B1: C (proportional to the product of the masses and inversely proportional to the square of their separation).', 1, NULL, NULL),
('28154548-2444-5189-94c5-0e47368fc167', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 14, 14, 'The distance between two point masses is tripled. What happens to the gravitational force between them?', NULL, 1, 'multiple_choice'::answer_type, 'It becomes one ninth as large', NULL, false, NULL, false, NULL, 'F ∝ 1/r². Tripling r divides F by 3² = 9. Mark scheme (1 mark). B1: A (It becomes one ninth as large).', 1, NULL, NULL),
('5b4c54e0-abd5-5110-bb12-2ef0362e4b0a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 15, 15, 'What is the value of the gravitational constant G, with its unit?', NULL, 1, 'multiple_choice'::answer_type, '6.67 × 10⁻¹¹ N m² kg⁻²', NULL, false, NULL, false, NULL, 'From F = Gm₁m₂/r², G = Fr²/(m₁m₂), so its unit is N m² kg⁻². Its value is 6.67 × 10⁻¹¹ N m² kg⁻². Mark scheme (1 mark). B1: D (6.67 × 10⁻¹¹ N m² kg⁻²).', 1, NULL, NULL),
('97bc4de6-d4bf-5556-aa11-08f954e7f551', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 16, 16, 'Why can a planet be treated as a point mass when calculating the gravitational force on a distant satellite?', NULL, 1, 'multiple_choice'::answer_type, 'Its mass is distributed spherically symmetrically, so it acts as if concentrated at its centre', NULL, false, NULL, false, NULL, 'For a spherically symmetric body, the field outside it is the same as if all the mass were at the centre. Mark scheme (1 mark). B1: B (Its mass is distributed spherically symmetrically, so it acts as if concentrated at its centre).', 1, NULL, NULL),
('9c137939-56d0-57a7-87d8-ac27495a911d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 17, 17, 'Calculate the gravitational field strength 350 km above the Earth''s surface. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '8.818', 'N kg⁻¹', false, NULL, false, NULL, 'r = 6.37 × 10⁶ + 3.5 × 10⁵ = 6.72 × 10⁶ m. g = GM/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ (6.72 × 10⁶)² = 8.82 N kg⁻¹. Mark scheme (2 marks). C1: r = R + h. A1: g = 8.82 N kg⁻¹.', 2, NULL, NULL),
('28548c38-f29b-57b4-a98c-4a2782b90e06', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 18, 18, 'The Sun has mass 1.99 × 10³⁰ kg. Calculate its gravitational field strength at the Earth''s orbit, 1.50 × 10¹¹ m away. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '0.005899', 'N kg⁻¹', false, NULL, false, NULL, 'g = GM/r² = 6.67 × 10⁻¹¹ × 1.99 × 10³⁰ ÷ (1.50 × 10¹¹)² = 0.00590 N kg⁻¹. Mark scheme (2 marks). C1: g = GM/r². A1: g = 0.00590 N kg⁻¹.', 2, NULL, NULL),
('4396ddc4-82bf-504f-9570-19d01c034526', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 19, 19, 'The gravitational field strength at the surface of a planet is g. What is it at a height above the surface equal to the planet''s radius?', NULL, 1, 'multiple_choice'::answer_type, 'g/4', NULL, false, NULL, false, NULL, 'At that height the distance from the centre is 2R, and g ∝ 1/r², so it is g/2² = g/4. Mark scheme (1 mark). B1: C (g/4).', 1, NULL, NULL),
('e8ab7d19-663c-5dbc-85a0-63a8bdd61aa4', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 20, 20, 'A 1.0 kg mass and a 4.0 kg mass are 0.20 m apart. Calculate the gravitational force between them. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '6.67e-9', 'N', false, NULL, false, NULL, 'F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 1.0 × 4.0 ÷ 0.20² = 6.67 × 10⁻⁹ N. Mark scheme (2 marks). C1: F = Gm₁m₂/r². A1: F = 6.67 × 10⁻⁹ N.', 2, NULL, NULL),
('72d8d805-ae75-5d1d-b10b-db4b257b9c22', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 21, 21, 'Two masses attract each other with a force F. Both masses are doubled and their separation is doubled. What is the new force?', NULL, 1, 'multiple_choice'::answer_type, 'F', NULL, false, NULL, false, NULL, 'F ∝ m₁m₂/r²: the product of the masses rises by 4 and r² rises by 4, so the force is unchanged. Mark scheme (1 mark). B1: A (F).', 1, NULL, NULL),
('b3e7726c-c4da-5df3-bf82-28ea988f5c65', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 22, 22, 'Engineers designing a Mercury lander need the planet''s surface gravity. Mercury is a sphere of radius 2.44 × 10⁶ m and mass 3.30 × 10²³ kg. Find g at its surface. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '3.697', 'N kg⁻¹', false, NULL, false, NULL, 'g = GM/R² = 6.67 × 10⁻¹¹ × 3.30 × 10²³ ÷ (2.44 × 10⁶)² = 3.70 N kg⁻¹. Mark scheme (2 marks). C1: g = GM/R². A1: g = 3.70 N kg⁻¹.', 2, NULL, NULL),
('b1adf3af-88cf-5c8c-8a84-091ff349a138', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 23, 23, 'Which equation gives the gravitational field strength g at a distance r from the centre of a planet of mass M?', NULL, 1, 'multiple_choice'::answer_type, 'g = GM/r²', NULL, false, NULL, false, NULL, 'The force on a mass m is GMm/r², so the force per unit mass is GM/r². (−GM/r is the potential, not the field strength.). Mark scheme (1 mark). B1: D (g = GM/r²).', 1, NULL, NULL),
('c9bfc681-5995-5b45-aa38-994effb3ee86', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 24, 24, 'Find the gravitational force exerted by a 0.50 kg lead sphere on a 0.020 kg ball whose centre is 6.0 cm from the sphere''s centre. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '1.853e-10', 'N', false, NULL, false, NULL, 'F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 0.50 × 0.020 ÷ 0.060² = 1.85 × 10⁻¹⁰ N. Mark scheme (2 marks). C1: r in metres. A1: F = 1.85 × 10⁻¹⁰ N.', 2, NULL, NULL),
('12f27b79-2396-56a5-80cc-8a3fe126c926', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 25, 25, 'The Earth pulls the Moon with a force F. What is the size of the force the Moon exerts on the Earth?', NULL, 1, 'multiple_choice'::answer_type, 'F, because forces between bodies are an equal and opposite pair', NULL, false, NULL, false, NULL, 'By Newton''s third law the gravitational forces on the two bodies are equal in size and opposite in direction, whatever their masses. Gm₁m₂/r² is the same for both. Mark scheme (1 mark). B1: B (F, because forces between bodies are an equal and opposite pair).', 1, NULL, NULL),
('8796ebb1-f9fe-519b-93ed-9f35d21ce14f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 26, 26, 'A planet''s radius is doubled while its mass stays the same. What happens to the gravitational field strength at its surface?', NULL, 1, 'multiple_choice'::answer_type, 'It falls to one quarter', NULL, false, NULL, false, NULL, 'g = GM/R²: doubling R with M fixed divides g by 4. Mark scheme (1 mark). B1: A (It falls to one quarter).', 1, NULL, NULL),
('02a45e3d-4bd0-5ffb-9924-1f8a6d85366d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 27, 27, 'A satellite orbits at a height of 6.37 × 10⁶ m above the Earth''s surface (one Earth radius). The surface field strength is 9.81 N kg⁻¹. Without using G, calculate g at the satellite.', NULL, 2, 'numeric'::answer_type, '2.453', 'N kg⁻¹', false, NULL, false, NULL, 'Distance from centre = 2R. g ∝ 1/r², so g = 9.81 × (R/2R)² = 9.81 ÷ 4 = 2.45 N kg⁻¹. Mark scheme (3 marks). C1: r = 2R. C1: inverse-square ratio. A1: g = 2.45 N kg⁻¹. Common mistake: using the height (R) instead of the distance from the centre (2R).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fgd8924187-t fgd8924187-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgd8924187-t">Satellite one Earth radius up</title><desc id="fgd8924187-d">The Earth (radius 6.37 × 10⁶ m) and a satellite orbiting 6.37 × 10⁶ m above the surface, so its orbit radius is two Earth radii.</desc><circle cx="180" cy="160" r="63" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="180" y="160" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">Earth</text><circle cx="180" cy="160" r="126" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="174" y="30" width="12" height="8" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,97 177,90.7 183,90.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="180" y1="92.1" x2="180" y2="43.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,39 183,45.3 177,45.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="188" y="70.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">6.37 × 10⁶ m</text></svg>', 'The Earth (radius 6.37 × 10⁶ m) and a satellite orbiting 6.37 × 10⁶ m above the surface, so its orbit radius is two Earth radii.'),
('57c88278-7722-5624-a893-c18ea7383f50', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 28, 28, 'At what height above the Earth''s surface is the gravitational field strength equal to 1.0 N kg⁻¹? Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '1.358e7', 'm', false, NULL, false, NULL, 'r = √(GM/g) = √(6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ 1.0) = 2.00 × 10⁷ m. Height = r − R = 1.995 × 10⁷ − 6.37 × 10⁶ = 1.36 × 10⁷ m. Mark scheme (4 marks). C1: g = GM/r². C1: r = √(GM/g). C1: subtract R. A1: h = 1.36 × 10⁷ m.', 4, NULL, NULL),
('7bfb500d-bbc7-5ff5-b69e-4c7403c2bb18', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 29, 29, 'The Earth''s surface field strength is 9.81 N kg⁻¹. Use this and the Earth''s radius (6.37 × 10⁶ m) to calculate the mass of the Earth. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '5.968e24', 'kg', false, NULL, false, NULL, 'g = GM/R², so M = gR²/G = 9.81 × (6.37 × 10⁶)² ÷ 6.67 × 10⁻¹¹ = 5.97 × 10²⁴ kg. Mark scheme (3 marks). C1: g = GM/R². C1: M = gR²/G. A1: M = 5.97 × 10²⁴ kg.', 3, NULL, NULL),
('f0c27014-b1d9-5a80-8f20-71911ce02709', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 30, 30, 'Planet P has twice the mass of planet Q and three times its radius. What is the ratio (surface field strength of P)/(surface field strength of Q)?', NULL, 2, 'multiple_choice'::answer_type, '2/9', NULL, false, NULL, false, NULL, 'g = GM/R² ∝ M/R²: ratio = 2 ÷ 3² = 2/9. Mark scheme (3 marks). C1: g ∝ M/R². C1: ratio. A1: C (2/9).', 3, NULL, NULL),
('4cbb11c4-adca-56c5-a0e5-ba0f73b9ff83', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 31, 31, 'Calculate the acceleration of the Moon towards the Earth due to the Earth''s gravity. The Earth–Moon distance is 3.84 × 10⁸ m. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '0.0027', 'm s⁻²', false, NULL, false, NULL, 'a = g at the Moon = GM/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ (3.84 × 10⁸)² = 0.00270 m s⁻². (The Moon''s mass is not needed.). Mark scheme (3 marks). B1: acceleration = field strength. C1: g = GM/r². A1: a = 0.00270 m s⁻².', 3, NULL, NULL),
('8dba971d-c3bb-5de4-9236-59fe7b07025c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 32, 32, 'Two lead spheres of mass 150 kg each have their centres 0.40 m apart. A student says the gravitational force between them is "too small to measure". Calculate the force, and compare it with the weight of a 1 mg grain of sand. Give the force. Take G = 6.67 × 10⁻¹¹ N m² kg⁻². Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '9.38e-6', 'N', false, NULL, false, NULL, 'F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 150 × 150 ÷ 0.40² = 9.38 × 10⁻⁶ N. The grain weighs 1 × 10⁻⁶ × 9.81 = 9.8 × 10⁻⁶ N — about the same as this force, so it is tiny but measurable with a sensitive torsion balance. Mark scheme (3 marks). C1: F = Gm₁m₂/r². C1: substitution. B1: comparison.', 3, NULL, NULL),
('ee594045-9c45-5bd1-a2ad-80b9f0b945d0', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 33, 33, 'A spacecraft travels away from the Earth. At distance r from the centre the field strength is g. At what distance is the field strength g/16?', NULL, 2, 'multiple_choice'::answer_type, '4r', NULL, false, NULL, false, NULL, 'g ∝ 1/r². For g to fall by 16, r must increase by √16 = 4. Mark scheme (3 marks). C1: g ∝ 1/r². C1: √16 = 4. A1: A (4r).', 3, NULL, NULL),
('b7926a91-4d12-5b5e-aa9a-104373e2a08a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 34, 34, 'A neutron star has a mass of 2.8 × 10³⁰ kg and a radius of 12 km. Calculate the gravitational field strength at its surface, and express it as a multiple of g on Earth (9.81 N kg⁻¹). Give the multiple. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '1.322e11', NULL, false, NULL, false, NULL, 'g = GM/R² = 6.67 × 10⁻¹¹ × 2.8 × 10³⁰ ÷ 12000² = 1.30 × 10¹² N kg⁻¹. Multiple = 1.30 × 10¹² ÷ 9.81 = 1.32 × 10¹¹. Mark scheme (4 marks). C1: R in metres. C1: g = GM/R². C1: ÷ 9.81. A1: multiple = 1.32 × 10¹¹.', 4, NULL, NULL),
('9d162efe-1a2d-5611-868c-ea2b2351c630', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 35, 35, 'A 1500 kg satellite is in orbit 2.0 × 10⁷ m from the Earth''s centre. Calculate the gravitational force on it. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '1493', 'N', false, NULL, false, NULL, 'F = GMm/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 1500 ÷ (2.0 × 10⁷)² = 1490 N. Mark scheme (3 marks). C1: F = GMm/r². C1: r is distance from centre. A1: F = 1490 N.', 3, NULL, NULL),
('48874e0b-bff1-5bc9-815e-1db2f92ddaf5', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 36, 36, 'The Moon''s mass is 1/81 of the Earth''s and its radius is 0.27 times the Earth''s. Approximately what fraction of the Earth''s surface field strength is the Moon''s?', NULL, 2, 'multiple_choice'::answer_type, '1/6', NULL, false, NULL, false, NULL, 'g ∝ M/R²: (1/81) ÷ 0.27² = (1/81) ÷ 0.0729 = 0.17 ≈ 1/6. Mark scheme (3 marks). C1: g ∝ M/R². C1: calculation. A1: D (1/6).', 3, NULL, NULL),
('b30afb13-aeea-55c3-a1e3-6aee824d6836', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 37, 37, 'A comet passes the Sun at a distance of 8.0 × 10⁹ m. Its mass is 2.2 × 10¹⁴ kg. Calculate (a) the Sun''s field strength there and (b) the force on the comet. Sun''s mass = 1.99 × 10³⁰ kg. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '4.563e14', 'N', false, NULL, false, NULL, '(a) g = GM/r² = 6.67 × 10⁻¹¹ × 1.99 × 10³⁰ ÷ (8.0 × 10⁹)² = 2.07 N kg⁻¹. (b) F = mg = 2.2 × 10¹⁴ × 2.07 = 4.56 × 10¹⁴ N. Mark scheme (4 marks). C1: g = GM/r². C1: F = mg. C1: substitution. A1: F = 4.56 × 10¹⁴ N.', 4, NULL, NULL),
('d2a1fc50-9268-5d82-bcbc-de88e2d50b13', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 38, 38, 'At the surface of a planet of radius R, g = 12.0 N kg⁻¹. Calculate g at a height of 0.50R above the surface.', NULL, 2, 'numeric'::answer_type, '5.333', 'N kg⁻¹', false, NULL, false, NULL, 'r = 1.5R. g = 12.0 × (1/1.5)² = 5.33 N kg⁻¹. Mark scheme (3 marks). C1: r = 1.5R. C1: inverse square. A1: g = 5.33 N kg⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fgf32dcde5-t fgf32dcde5-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf32dcde5-t">Point above a planet</title><desc id="fgf32dcde5-d">A planet of radius R with surface field strength 12.0 N kg⁻¹, and a point at a height of 0.50R above the surface (1.5R from the centre).</desc><circle cx="180" cy="160" r="84" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="180" y="160" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">radius R</text><circle cx="180" cy="160" r="126" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><polygon points="180,76 177,69.7 183,69.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="180" y1="71.1" x2="180" y2="38.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,34 183,40.3 177,40.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="188" y="60" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">0.50R</text></svg>', 'A planet of radius R with surface field strength 12.0 N kg⁻¹, and a point at a height of 0.50R above the surface (1.5R from the centre).'),
('ad6f5ab6-3a08-5160-90c4-95357f3f27b2', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 39, 39, 'A student measures the weight of a mass at the Earth''s surface and then on a mountain 4 km high. Which best describes the result?', NULL, 2, 'multiple_choice'::answer_type, 'The weight on the mountain is about 0.1 % smaller', NULL, false, NULL, false, NULL, 'r increases from 6370 km to 6374 km: g falls by a factor (6370/6374)² ≈ 0.9987, a decrease of about 0.13 %. Mark scheme (3 marks). C1: r from centre changes by 4 km out of 6370 km. C1: inverse-square fraction. A1: B (The weight on the mountain is about 0.1 % smaller).', 3, NULL, NULL),
('a9a3b918-91c0-5a4e-9d2c-773c535eda3a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 40, 40, 'The gravitational force between two identical spheres is 2.5 × 10⁻⁸ N when their centres are 0.30 m apart. Calculate the mass of each sphere. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '5.808', 'kg', false, NULL, false, NULL, 'F = Gm²/r², so m = r√(F/G) = √(2.5 × 10⁻⁸ × 0.30² ÷ 6.67 × 10⁻¹¹) = 5.81 kg. Mark scheme (4 marks). C1: F = Gm²/r². C1: rearranged. C1: square root. A1: m = 5.81 kg.', 4, NULL, NULL),
('377d3dfd-a9c0-5064-af21-2653952d83e7', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 41, 41, 'A probe measures g = 0.53 N kg⁻¹ at a distance of 5.0 × 10⁷ m from the centre of an unknown moon. Calculate the moon''s mass. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '1.987e25', 'kg', false, NULL, false, NULL, 'M = gr²/G = 0.53 × (5.0 × 10⁷)² ÷ 6.67 × 10⁻¹¹ = 1.99 × 10²⁵ kg. Mark scheme (3 marks). C1: g = GM/r². C1: rearranged for M. A1: M = 1.99 × 10²⁵ kg.', 3, NULL, NULL),
('8640ec1d-e861-54e7-9b53-845f27a02236', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 42, 42, 'Why do we usually ignore the gravitational force between two people standing next to each other?', NULL, 2, 'multiple_choice'::answer_type, 'It is about 10⁻⁷ N, far smaller than every other force on them', NULL, false, NULL, false, NULL, 'For two 70 kg people 1 m apart, F = 6.67 × 10⁻¹¹ × 70 × 70 ÷ 1² ≈ 3 × 10⁻⁷ N, utterly negligible compared with their weights (≈ 700 N) or friction. Mark scheme (3 marks). C1: estimate of the force. C1: comparison with other forces. A1: C (It is about 10⁻⁷ N, far smaller than every other force on them).', 3, NULL, NULL),
('047a2b65-d29f-523e-abb2-bae2117a51d8', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 43, 43, 'At what distance from the centre of the Earth would a 70 kg person weigh 100 N? Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '1.67e7', 'm', false, NULL, false, NULL, 'F = GMm/r², so r = √(GMm/F) = √(3.98 × 10¹⁴ × 70 ÷ 100) = 1.67 × 10⁷ m. Mark scheme (3 marks). C1: F = GMm/r². C1: rearranged for r. A1: r = 1.67 × 10⁷ m.', 3, NULL, NULL),
('1ce109bb-0869-543f-80f9-53ad1c4d80d4', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 44, 44, 'The Moon''s mass is 1/81 of the Earth''s. Their centres are 3.84 × 10⁸ m apart. (a) Explain why a spacecraft travelling between them feels no resultant gravitational force at one point. (b) Show that this point is 9/10 of the way from the Earth to the Moon. (c) Calculate its distance from the Earth''s centre. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3.456e8', 'm', false, NULL, false, NULL, '(a) The two fields point in opposite directions between the bodies; at one point they are equal in size. (b) GM_E/x² = G(M_E/81)/(d − x)² gives (d − x)/x = 1/9, so x = 9d/10. (c) x = 0.9 × 3.84 × 10⁸ = 3.46 × 10⁸ m. Mark scheme (6 marks). B1: opposite fields. M1: GM_E/x² = GM_M/(d − x)². M1: square root: x/(d − x) = 9. A1: x = 9d/10. C1: substitution. A1: x = 3.46 × 10⁸ m.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 159.8" role="img" aria-labelledby="fg894cc09c-t fg894cc09c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg894cc09c-t">Earth and Moon</title><desc id="fg894cc09c-d">The Earth and the Moon (mass 1/81 of the Earth''s) with centres 3.84 × 10⁸ m apart.</desc><polygon points="70,101.8 76.3,98.8 76.3,104.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="101.8" x2="345.1" y2="101.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="350,101.8 343.7,104.7 343.7,98.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="210" y="113.8" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.84 × 10⁸ m</text><circle cx="70" cy="58" r="22" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Earth</text><circle cx="350" cy="58" r="8" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="350" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Moon</text></svg>', 'The Earth and the Moon (mass 1/81 of the Earth''s) with centres 3.84 × 10⁸ m apart.'),
('3ebcacd6-7be5-57cc-b4a8-74837a96138d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 45, 45, 'The Moon (mass 7.35 × 10²² kg) is pulled by both the Earth and the Sun. Earth–Moon distance 3.84 × 10⁸ m; Sun–Moon distance 1.50 × 10¹¹ m; Sun''s mass 1.99 × 10³⁰ kg. (a) Calculate the Earth''s pull on the Moon. (b) Calculate the Sun''s pull on the Moon. (c) Calculate the ratio (Sun''s pull)/(Earth''s pull) and comment. Give only the ratio in (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '2.185', NULL, false, NULL, false, NULL, '(a) F = GM_Em/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 7.35 × 10²² ÷ (3.84 × 10⁸)² = 1.98 × 10²⁰ N. (b) F = 6.67 × 10⁻¹¹ × 1.99 × 10³⁰ × 7.35 × 10²² ÷ (1.50 × 10¹¹)² = 4.34 × 10²⁰ N. (c) ratio = 4.336 × 10²⁰ ÷ 1.985 × 10²⁰ = 2.18: the Sun pulls the Moon about twice as hard as the Earth does, but it pulls the Earth too, so the Moon still orbits the Earth. Mark scheme (6 marks). C1: F = GMm/r². A1: Earth''s pull. A1: Sun''s pull. C1: ratio. B1: comment. A1: ratio = 2.18.', 6, NULL, NULL),
('eb7043d3-ce0b-5793-90e0-caa16b9eee41', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 46, 46, 'A planet of radius 4.0 × 10⁶ m has a surface field strength of 6.0 N kg⁻¹. (a) Calculate its mass. (b) Calculate the height above its surface at which g = 1.5 N kg⁻¹. (c) Explain why the answer to (b) does not depend on the value of G. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '4e6', 'm', false, NULL, false, NULL, '(a) M = gR²/G = 6.0 × (4.0 × 10⁶)² ÷ 6.67 × 10⁻¹¹ = 1.44 × 10²⁴ kg. (b) g falls by 4, so r doubles: r = 2 × 4.0 × 10⁶ = 8.0 × 10⁶ m, height = 8.0 × 10⁶ − 4.0 × 10⁶ = 4.0 × 10⁶ m. (c) Only the ratio g/g₀ = (R/r)² is used; G cancels. Mark scheme (5 marks). C1: M = gR²/G. A1: M. M1: g ∝ 1/r², factor 4 → r doubles. A1: h = 4.0 × 10⁶ m. B1: ratio method, G cancels.', 5, NULL, NULL),
('98814dfb-d420-52c8-895e-af1065fdc3d5', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 47, 47, 'A probe records g at different distances r from the centre of the Earth: r = 7.0 × 10⁶ m, g = 8.13 N kg⁻¹; r = 1.0 × 10⁷ m, g = 3.98 N kg⁻¹; r = 2.0 × 10⁷ m, g = 0.995 N kg⁻¹; r = 4.0 × 10⁷ m, g = 0.249 N kg⁻¹. (a) Suggest a graph to plot to test g = GM/r². (b) Use the data at r = 2.0 × 10⁷ m to determine GM. (c) Hence calculate the mass of the Earth. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '5.967e24', 'kg', false, NULL, false, NULL, '(a) g against 1/r²: a straight line through the origin of gradient GM. (b) GM = gr² = 0.995 × (2.0 × 10⁷)² = 3.98 × 10¹⁴ N m² kg⁻¹. (c) M = GM/G = 3.98 × 10¹⁴ ÷ 6.67 × 10⁻¹¹ = 5.97 × 10²⁴ kg. Mark scheme (6 marks). B1: g against 1/r². B1: straight line through origin. C1: GM = gr². A1: GM. C1: M = GM/G. A1: M = 5.97 × 10²⁴ kg.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg53197821-t fg53197821-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg53197821-t">Field strength against distance</title><desc id="fg53197821-d">Graph of the probe readings of g against distance from the Earth''s centre, falling steeply as r increases.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="105.4" y1="34" x2="105.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="186.7" y1="34" x2="186.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="268.1" y1="34" x2="268.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="349.5" y1="34" x2="349.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="195.8" x2="382" y2="195.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="149.6" x2="382" y2="149.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="103.3" x2="382" y2="103.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="57.1" x2="382" y2="57.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="24" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="24,24 27,30.3 21,30.3" style="fill:currentColor;stroke:none"/><line x1="24" y1="242" x2="24" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="105.4" y1="242" x2="105.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="105.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="186.7" y1="242" x2="186.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="186.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="268.1" y1="242" x2="268.1" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="268.1" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="349.5" y1="242" x2="349.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="349.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="20" y1="242" x2="24" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="20" y1="195.8" x2="24" y2="195.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="195.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="20" y1="149.6" x2="24" y2="149.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="149.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="20" y1="103.3" x2="24" y2="103.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="103.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">6</text><line x1="20" y1="57.1" x2="24" y2="57.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="57.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">8</text><text x="203" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r / 10⁷ m</text><text x="20" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">g / N kg⁻¹</text><line x1="101.4" y1="146" x2="109.4" y2="154" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="101.4" y1="154" x2="109.4" y2="146" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="182.7" y1="215" x2="190.7" y2="223" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="182.7" y1="223" x2="190.7" y2="215" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="345.5" y1="232.2" x2="353.5" y2="240.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="345.5" y1="240.2" x2="353.5" y2="232.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Graph of the probe readings of g against distance from the Earth''s centre, falling steeply as r increases.'),
('9cb7214b-8341-53b5-8e6d-d72fa2536959', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 48, 48, 'Two stars orbit their common centre. Star A has mass 3.0 × 10³⁰ kg and star B has mass 1.0 × 10³⁰ kg; their centres are 2.0 × 10¹¹ m apart. (a) Calculate the gravitational force between them. (b) State and explain how the force on A compares with the force on B. (c) Calculate the acceleration of star B. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '0.005003', 'm s⁻²', false, NULL, false, NULL, '(a) F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 3.0 × 10³⁰ × 1.0 × 10³⁰ ÷ (2.0 × 10¹¹)² = 5.00 × 10²⁷ N. (b) Equal in size and opposite in direction (Newton''s third law). (c) a_B = F/m_B = 5.00 × 10²⁷ ÷ 1.0 × 10³⁰ = 0.00500 m s⁻². Mark scheme (5 marks). C1: Newton''s law. A1: F. B1: equal and opposite. C1: a = F/m. A1: a = 0.00500 m s⁻².', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 164" role="img" aria-labelledby="fg4c2f55ac-t fg4c2f55ac-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4c2f55ac-t">Binary stars</title><desc id="fg4c2f55ac-d">Star A (3.0 × 10³⁰ kg) and star B (1.0 × 10³⁰ kg), centres 2.0 × 10¹¹ m apart, orbiting their common centre C.</desc><polygon points="70,110 76.3,107 76.3,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="110" x2="345.1" y2="110" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="350,110 343.7,113 343.7,107" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="210" y="122" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 × 10¹¹ m</text><circle cx="70" cy="54" r="18" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">A</text><circle cx="350" cy="54" r="11" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="350" y="31" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">B</text><circle cx="140" cy="54" r="3.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="140" y="74" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">C</text></svg>', 'Star A (3.0 × 10³⁰ kg) and star B (1.0 × 10³⁰ kg), centres 2.0 × 10¹¹ m apart, orbiting their common centre C.'),
('a3ad8e97-0af2-5665-9ef6-9426897abf69', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 49, 49, 'A spherical asteroid has a mean density of 2500 kg m⁻³ and radius 5.0 km. (a) Calculate its mass. (b) Calculate g at its surface. (c) A rock is dropped from 2.0 m above the surface. Calculate the time it takes to land, assuming g is constant. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '33.84', 's', false, NULL, false, NULL, '(a) M = ρ × ⁴⁄₃πR³ = 2500 × ⁴⁄₃ × π × 5000³ = 1.31 × 10¹⁵ kg. (b) g = GM/R² = 6.67 × 10⁻¹¹ × 1.31 × 10¹⁵ ÷ 5000² = 0.00349 N kg⁻¹. (c) t = √(2s/g) = √(2 × 2.0 ÷ 0.00349) = 33.8 s. Mark scheme (6 marks). C1: M = ρV. A1: M. C1: g = GM/R². A1: g. C1: s = ½gt². A1: t = 33.8 s.', 6, NULL, NULL),
('600512e7-3b99-5a2a-a05f-57544070bfcb', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 50, 50, 'In a Cavendish-type experiment, a 0.73 kg lead ball is attracted by a 158 kg lead sphere whose centre is 0.23 m away. (a) Calculate the gravitational force on the small ball. (b) Calculate the acceleration this would give the small ball if it were free to move. (c) Explain why such experiments must be shielded from air currents. Give only the answer to (a). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '1.454e-7', 'N', false, NULL, false, NULL, '(a) F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 0.73 × 158 ÷ 0.23² = 1.45 × 10⁻⁷ N. (b) a = F/m = 1.45 × 10⁻⁷ ÷ 0.73 = 1.99 × 10⁻⁷ m s⁻². (c) The gravitational force is about 10⁻⁷ N: tiny air movements exert comparable forces and would swamp it. Mark scheme (5 marks). C1: F = Gm₁m₂/r². A1: F. C1: a = F/m. A1: F = 1.45 × 10⁻⁷ N. B1: force tiny compared with disturbances.', 5, NULL, NULL),
('48874e52-587f-5fe9-bdac-ea30fec9db82', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 51, 51, 'A satellite in orbit 8.0 × 10⁶ m from the Earth''s centre measures g = 6.22 N kg⁻¹. At the Earth''s surface, g = 9.81 N kg⁻¹. (a) Use only these values to show that the Earth''s radius is about 6.4 × 10⁶ m. (b) Calculate g at 1.6 × 10⁷ m from the Earth''s centre. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.555', 'N kg⁻¹', false, NULL, false, NULL, '(a) g ∝ 1/r²: R = 8.0 × 10⁶ × √(6.22 ÷ 9.81) = 6.37 × 10⁶ m ≈ 6.4 × 10⁶ m. (b) Doubling r quarters g: g = 6.22 ÷ 4 = 1.55 N kg⁻¹. Mark scheme (5 marks). M1: inverse-square ratio. M1: R = r√(g/g₀). A1: R ≈ 6.4 × 10⁶ m. C1: r doubles. A1: g = 1.55 N kg⁻¹.', 5, NULL, NULL),
('96eea422-d995-5128-ab39-fd4de3fd0cde', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '17.2', '9702 coursebook 17.2 · Field strength of a point mass', 52, 52, 'Tides are caused because the Moon pulls the near side of the Earth harder than the far side. Moon''s mass = 7.35 × 10²² kg, Earth–Moon centre distance = 3.84 × 10⁸ m, Earth''s radius = 6.37 × 10⁶ m. (a) Calculate the Moon''s field strength at the point on the Earth nearest the Moon. (b) Calculate it at the point furthest from the Moon. (c) Calculate the difference. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '2.207e-6', 'N kg⁻¹', false, NULL, false, NULL, '(a) g = GM/r² = 6.67 × 10⁻¹¹ × 7.35 × 10²² ÷ (3.7763 × 10⁸)² = 3.438 × 10⁻⁵ N kg⁻¹. (b) g = 6.67 × 10⁻¹¹ × 7.35 × 10²² ÷ (3.9037 × 10⁸)² = 3.217 × 10⁻⁵ N kg⁻¹. (c) difference = 3.438 × 10⁻⁵ − 3.217 × 10⁻⁵ = 2.21 × 10⁻⁶ N kg⁻¹. Mark scheme (6 marks). C1: near-side distance d − R. A1: g near. C1: far-side distance d + R. A1: g far. B1: difference (about 7%). A1: Δg = 2.2 × 10⁻⁶ N kg⁻¹.', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
