('c01c8b88-b861-5c4d-a933-d99b15dc5c14', '8640ec1d-e861-54e7-9b53-845f27a02236', 'Gravity only acts between very large masses', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('3745ed58-1e51-5e55-8389-053f6f55098e', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 7, 7, 'A 2.0 kg bag of flour is lifted onto a shelf 3.5 m higher. Calculate its gain in gravitational potential energy. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '68.67', 'J', false, NULL, false, NULL, 'ΔEp = mgΔh = 2.0 × 9.81 × 3.5 = 68.7 J. Mark scheme (1 mark). A1: ΔEp = 68.7 J.', 1, NULL, NULL),
('5fe9e433-3185-59b3-bbb6-1e582e521e3b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 8, 8, 'A 65 kg hiker climbs a hill 420 m high. Calculate the gravitational potential energy she gains. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '2.678e5', 'J', false, NULL, false, NULL, 'ΔEp = mgΔh = 65 × 9.81 × 420 = 2.68 × 10⁵ J. Mark scheme (2 marks). C1: ΔEp = mgΔh. A1: ΔEp = 2.68 × 10⁵ J.', 2, NULL, NULL),
('33cd3405-1379-5459-ab88-17067a0e949e', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 9, 9, 'Why can ΔEp = mgΔh be used for a crane lifting a load but not for a rocket leaving the Earth?', NULL, 1, 'multiple_choice'::answer_type, 'g is almost constant over a few metres but falls significantly over thousands of kilometres', NULL, false, NULL, false, NULL, 'mgΔh assumes a uniform field. Over large distances g = GM/r² decreases, so the energy change must be found from −GMm/r. Mark scheme (1 mark). B1: C (g is almost constant over a few metres but falls significantly over thousands of kilometres).', 1, NULL, NULL),
('301e0c45-a921-553a-982e-58199fcc2320', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 10, 10, 'Where is the zero of gravitational potential energy taken when using Ep = −GMm/r?', NULL, 1, 'multiple_choice'::answer_type, 'At an infinite distance from the mass', NULL, false, NULL, false, NULL, 'Ep = −GMm/r tends to zero as r → ∞, so zero is defined at infinity; everywhere nearer it is negative. Mark scheme (1 mark). B1: A (At an infinite distance from the mass).', 1, NULL, NULL),
('7ab43ee0-55f5-5326-ac65-29771181d58d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 11, 11, 'Calculate the gravitational potential energy of a 1.0 kg mass at the Earth''s surface, taking zero at infinity. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '-6.251e7', 'J', false, NULL, true, NULL, 'Ep = −GMm/r = −6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 1.0 ÷ 6.37 × 10⁶ = −6.25 × 10⁷ J. Mark scheme (2 marks). C1: Ep = −GMm/r. A1: Ep = −6.25 × 10⁷ J.', 2, NULL, NULL),
('b68f5d3b-f55b-5a00-83fd-1a2a54b87d7b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 12, 12, 'A satellite moves from a low orbit to a higher orbit. What happens to its gravitational potential energy?', NULL, 1, 'multiple_choice'::answer_type, 'It increases (becomes less negative)', NULL, false, NULL, false, NULL, 'Ep = −GMm/r. Larger r makes Ep less negative, i.e. larger. Work must be done against gravity to raise the satellite. Mark scheme (1 mark). B1: D (It increases (becomes less negative)).', 1, NULL, NULL),
('00687bb5-3c0c-5a0b-9444-d64070cf1935', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 13, 13, 'Which quantity is the work done per unit mass in bringing a small mass from infinity to a point in a gravitational field?', NULL, 1, 'multiple_choice'::answer_type, 'The gravitational potential at the point', NULL, false, NULL, false, NULL, 'Gravitational potential φ is defined as the work done per unit mass in bringing a small test mass from infinity to the point. It is negative because the field does the work. Mark scheme (1 mark). B1: B (The gravitational potential at the point).', 1, NULL, NULL),
('759bba93-ba22-5567-936a-47fe62ea74d8', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 14, 14, 'A 0.15 kg ball is thrown up and rises 18 m. Calculate the minimum speed it was thrown with (ignore air resistance). Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '18.79', 'm s⁻¹', false, NULL, false, NULL, '½mv² = mgh, so v = √(2gh) = √(2 × 9.81 × 18) = 18.8 m s⁻¹. Mark scheme (2 marks). C1: ½mv² = mgh. A1: v = 18.8 m s⁻¹.', 2, NULL, NULL),
('18350a05-d059-5267-80ef-e3cb29624408', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 15, 15, 'A 1200 kg lift rises 35 m at constant speed. How much work does the motor do against gravity? Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '4.12e5', 'J', false, NULL, false, NULL, 'W = mgΔh = 1200 × 9.81 × 35 = 4.12 × 10⁵ J. Mark scheme (2 marks). C1: work = gain in Ep. A1: W = 4.12 × 10⁵ J.', 2, NULL, NULL),
('c7df0060-4afd-5571-9335-41447117a339', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 16, 16, 'Gravitational potential energy near a planet is negative. Which statement explains this?', NULL, 1, 'multiple_choice'::answer_type, 'Work must be done on a mass to move it out to infinity, where Ep is zero', NULL, false, NULL, false, NULL, 'With zero at infinity, a mass near the planet has less energy than at infinity: energy must be supplied to remove it, so its Ep is below zero. Mark scheme (1 mark). B1: C (Work must be done on a mass to move it out to infinity, where Ep is zero).', 1, NULL, NULL),
('ad897947-6a85-501c-b481-870c636d1c86', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 17, 17, 'How much gravitational potential energy does a 5.0 kg mass lose when it falls 12 m on the Moon, where g = 1.62 N kg⁻¹?', NULL, 1, 'numeric'::answer_type, '97.2', 'J', false, NULL, false, NULL, 'ΔEp = mgΔh = 5.0 × 1.62 × 12 = 97.2 J. Mark scheme (2 marks). C1: ΔEp = mgΔh with Moon g. A1: ΔEp = 97.2 J.', 2, NULL, NULL),
('f3f87a40-b9da-5210-ac10-eee2866ed01e', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 18, 18, 'An object falls freely towards the Earth from a great height. Which describes the energy changes?', NULL, 1, 'multiple_choice'::answer_type, 'Ep becomes more negative and Ek increases by the same amount', NULL, false, NULL, false, NULL, 'Gravity does positive work on the falling object: its Ep decreases (more negative) and its Ek increases by the same amount, so the total energy is constant. Mark scheme (1 mark). B1: A (Ep becomes more negative and Ek increases by the same amount).', 1, NULL, NULL),
('538f2da0-49b5-53a5-bba4-afb09a6e3bd2', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 19, 19, 'A 420 kg space probe is at a distance of 2.0 × 10⁷ m from the Earth''s centre. Calculate its gravitational potential energy. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '-8.362e9', 'J', false, NULL, true, NULL, 'Ep = −GMm/r = −6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 420 ÷ 2.0 × 10⁷ = −8.36 × 10⁹ J. Mark scheme (2 marks). C1: Ep = −GMm/r. A1: Ep = −8.36 × 10⁹ J.', 2, NULL, NULL),
('58ecfb5e-f0de-54ec-8741-95f9be6aac18', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 20, 20, 'Which equation gives the escape speed from the surface of a planet of mass M and radius R?', NULL, 1, 'multiple_choice'::answer_type, 'v = √(2GM/R)', NULL, false, NULL, false, NULL, 'To escape, ½mv² ≥ GMm/R, so v = √(2GM/R). (√(GM/R) is the speed of a low circular orbit.). Mark scheme (1 mark). B1: D (v = √(2GM/R)).', 1, NULL, NULL),
('14d7241b-dd8e-5e0a-aa43-2b708a42978a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 21, 21, 'A 2.5 kg rock rolls down a cliff 60 m high on the Earth. Ignoring friction, calculate its speed at the bottom. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '34.31', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2gh) = √(2 × 9.81 × 60) = 34.3 m s⁻¹. Mark scheme (2 marks). C1: Ep lost = Ek gained. A1: v = 34.3 m s⁻¹.', 2, NULL, NULL),
('8f7c48f9-d9dc-51cf-b363-ab6854e3e6eb', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 22, 22, 'Does the escape speed from the Earth depend on the mass of the object being launched?', NULL, 1, 'multiple_choice'::answer_type, 'No: both ½mv² and GMm/R are proportional to m, so m cancels', NULL, false, NULL, false, NULL, '½mv² = GMm/R gives v = √(2GM/R), independent of m. Mark scheme (1 mark). B1: B (No: both ½mv² and GMm/R are proportional to m, so m cancels).', 1, NULL, NULL),
('cbee72a3-f379-53a8-b01c-5c67f8d94ae6', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 23, 23, 'A 60 kg diver steps off a 10 m platform. Calculate the kinetic energy she has gained just before reaching the water. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '5886', 'J', false, NULL, false, NULL, 'Ek = Ep lost = mgh = 60 × 9.81 × 10 = 5890 J. Mark scheme (2 marks). C1: energy conservation. A1: Ek = 5890 J.', 2, NULL, NULL),
('ab4ca170-33b7-59b9-a381-64f75d7d98d3', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 24, 24, 'A 0.20 kg apple falls 3.0 m from a tree. Calculate the decrease in its gravitational potential energy. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '5.886', 'J', false, NULL, false, NULL, 'ΔEp = mgh = 0.20 × 9.81 × 3.0 = 5.89 J. Mark scheme (2 marks). C1: ΔEp = mgh. A1: ΔEp = 5.89 J.', 2, NULL, NULL),
('004e72a6-36d2-5999-9187-6499f43e9160', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 25, 25, 'Calculate the work needed to lift a 1000 kg satellite from the Earth''s surface to a height of 400 km, using Ep = −GMm/r. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '3.693e9', 'J', false, NULL, false, NULL, 'ΔEp = GMm(1/r₁ − 1/r₂) = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 1000 × (1 ÷ 6.37 × 10⁶ − 1 ÷ 6.77 × 10⁶) = 3.69 × 10⁹ J. Mark scheme (3 marks). C1: ΔEp = −GMm/r₂ − (−GMm/r₁). C1: r₂ = R + h. C1: substitution.', 3, NULL, NULL),
('edc4f7d4-e37e-5ff4-a78a-4075a0abf83f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 26, 26, 'For the same lift (1000 kg, surface to 400 km) a student uses mgh with g = 9.81 N kg⁻¹. Calculate the percentage by which this overestimates the work, given that the true value is 3.69 × 10⁹ J. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '6.341', '%', false, NULL, false, NULL, 'mgh = 1000 × 9.81 × 4.0 × 10⁵ = 3.92 × 10⁹ J. Overestimate = (3.924 × 10⁹ ÷ 3.69 × 10⁹ − 1) × 100 = 6.3 %: g is smaller higher up, so mgh with surface g is too large. Mark scheme (3 marks). C1: mgh calculated. C1: percentage difference. B1: g decreases with height.', 3, NULL, NULL),
('304674cb-af46-578c-9c34-5da939ae6d60', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 27, 27, 'Calculate the escape speed from the surface of the Earth. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '11181', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2GM/R) = √(2 × 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ 6.37 × 10⁶) = 1.12 × 10⁴ m s⁻¹. Mark scheme (3 marks). C1: ½mv² = GMm/R. C1: v = √(2GM/R). A1: v_esc = 1.12 × 10⁴ m s⁻¹.', 3, NULL, NULL),
('695f5466-ef30-5dc3-bbd8-2fd91b5e742f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 28, 28, 'The Moon has mass 7.35 × 10²² kg and radius 1.74 × 10⁶ m. Calculate the escape speed from its surface, and suggest why the Moon has no atmosphere. Give the speed. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '2374', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2GM/R) = √(2 × 6.67 × 10⁻¹¹ × 7.35 × 10²² ÷ 1.74 × 10⁶) = 2370 m s⁻¹. Gas molecules in sunlight move fast enough that a fraction reach this speed and escape over time. Mark scheme (3 marks). C1: v = √(2GM/R). C1: substitution. B1: molecules escape.', 3, NULL, NULL),
('9f95c57b-eb2f-5224-9439-de4ce29dff3c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 29, 29, 'A satellite is moved from an orbit of radius r to one of radius 2r around the same planet. What happens to its gravitational potential energy?', NULL, 2, 'multiple_choice'::answer_type, 'It doubles in value but halves in size, i.e. from −X to −X/2', NULL, false, NULL, false, NULL, 'Ep = −GMm/r ∝ −1/r. Doubling r halves the magnitude: −X becomes −X/2, which is an increase. Mark scheme (3 marks). C1: Ep ∝ −1/r. C1: becomes less negative. A1: C (It doubles in value but halves in size, i.e. from −X to −X/2).', 3, NULL, NULL),
('6c9aa670-74a6-5a92-a194-63d896e74e71', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 30, 30, 'A 250 kg piece of space debris falls from rest at 7.0 × 10⁶ m from the Earth''s centre to 6.5 × 10⁶ m (ignore air resistance). Calculate the kinetic energy it gains. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '1.094e9', 'J', false, NULL, false, NULL, 'ΔEk = −ΔEp = GMm(1/r₂ − 1/r₁) = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 250 × (1 ÷ 6.5 × 10⁶ − 1 ÷ 7.0 × 10⁶) = 1.09 × 10⁹ J. Mark scheme (4 marks). C1: Ek gained = Ep lost. C1: GMm(1/r₂ − 1/r₁). C1: substitution. A1: ΔEk = 1.09 × 10⁹ J.', 4, NULL, NULL),
('dc84da64-ab0a-529d-add7-761193d5d197', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 31, 31, 'A rocket engine fails just as the rocket reaches the escape speed from the Earth, moving vertically. What happens next (ignore air resistance)?', NULL, 2, 'multiple_choice'::answer_type, 'It keeps moving away, slowing down, and its speed approaches zero as it approaches infinity', NULL, false, NULL, false, NULL, 'At exactly escape speed the total energy is zero. As r → ∞, Ep → 0, so Ek → 0: it slows but never quite stops and never returns. Mark scheme (3 marks). C1: total energy zero. C1: speed tends to zero at infinity. A1: A (It keeps moving away, slowing down, and its speed approaches zero as it approaches infinity).', 3, NULL, NULL),
('4d0da840-5570-5ae0-843b-6f60547da6a4', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 32, 32, 'Mars has mass 6.42 × 10²³ kg and radius 3.39 × 10⁶ m. A probe is launched from its surface at 3.0 km s⁻¹. Calculate the escape speed from Mars and decide whether the probe escapes. Give the escape speed. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '5026', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2GM/R) = √(2 × 6.67 × 10⁻¹¹ × 6.42 × 10²³ ÷ 3.39 × 10⁶) = 5030 m s⁻¹. 3.0 km s⁻¹ is less than this, so the probe does not escape (it falls back or, if launched sideways, orbits). Mark scheme (4 marks). C1: v = √(2GM/R). A1: escape speed. B1: conclusion. A1: v_esc = 5030 m s⁻¹.', 4, NULL, NULL),
('74c81b38-1eb7-5864-b603-33aade23b4de', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 33, 33, 'A ball is thrown vertically upwards from the surface of a small moon with g = 0.15 N kg⁻¹ at 2.0 m s⁻¹. Assuming g is constant, how high does it rise?', NULL, 2, 'numeric'::answer_type, '13.33', 'm', false, NULL, false, NULL, '½mv² = mgh, so h = v²/(2g) = 2.0² ÷ (2 × 0.15) = 13.3 m. Mark scheme (3 marks). C1: ½mv² = mgh. C1: rearrangement. A1: h = 13.3 m.', 3, NULL, NULL),
('d830efcc-13c8-58a3-ba19-e1c39c1e1129', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 34, 34, 'Why does a satellite in a stable circular orbit not need its engines to stay in orbit?', NULL, 2, 'multiple_choice'::answer_type, 'Gravity is perpendicular to its velocity, so it does no work and the kinetic energy is constant', NULL, false, NULL, false, NULL, 'In a circular orbit the gravitational force is always at 90° to the motion. It changes the direction but does no work, so the speed and energies stay constant. (Drag from the thin atmosphere is ignored.). Mark scheme (3 marks). C1: force perpendicular to velocity. C1: no work, so no energy change. A1: D (Gravity is perpendicular to its velocity, so it does no work and the kinetic energy is constant).', 3, NULL, NULL),
('4534ebd7-ba4d-5897-8936-2bbee3e04f08', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 35, 35, 'A 3.0 kg mass is moved from 1.0 × 10⁷ m to 2.0 × 10⁷ m from the centre of the Earth. Calculate the change in its gravitational potential energy, giving the sign. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '5.973e7', 'J', false, NULL, true, NULL, 'ΔEp = (−GMm/r₂) − (−GMm/r₁) = GMm(1/r₁ − 1/r₂) = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 3.0 × (1 ÷ 1.0 × 10⁷ − 1 ÷ 2.0 × 10⁷) = 5.97 × 10⁷ J (an increase). Mark scheme (4 marks). C1: Ep at each radius. C1: subtraction in the correct order. C1: substitution. A1: ΔEp = 5.97 × 10⁷ J.', 4, NULL, NULL),
('4f9d8cd1-057b-5608-8151-4cfd168539c1', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 36, 36, 'A small mass m falls from rest at a great distance (infinity) to the surface of a planet of mass M and radius R. What is its speed on arrival (no atmosphere)?', NULL, 2, 'multiple_choice'::answer_type, '√(2GM/R)', NULL, false, NULL, false, NULL, 'Energy conservation: 0 = ½mv² − GMm/R, so v = √(2GM/R): the escape speed in reverse. Mark scheme (4 marks). C1: total energy zero at infinity. C1: ½mv² = GMm/R. C1: rearranged. A1: B (√(2GM/R)).', 4, NULL, NULL),
('af15f93d-0831-5187-b7bd-b9d18b3cff2c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 37, 37, 'A 600 kg satellite in a circular orbit of radius 7.2 × 10⁶ m has kinetic energy GMm/2r. Calculate its kinetic energy. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '1.659e10', 'J', false, NULL, false, NULL, 'Ek = GMm/2r = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 600 ÷ (2 × 7.2 × 10⁶) = 1.66 × 10¹⁰ J. Mark scheme (3 marks). C1: Ek = GMm/2r. C1: substitution. A1: Ek = 1.66 × 10¹⁰ J.', 3, NULL, NULL),
('d5c7f37f-b03e-5c40-b88d-41cbdfd60658', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 38, 38, 'A meteorite is falling towards the Earth. At 1.0 × 10⁸ m from the centre it moves at 2.0 km s⁻¹. Ignoring the atmosphere, calculate its speed when it is 1.0 × 10⁷ m from the centre. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '8699', 'm s⁻¹', false, NULL, false, NULL, '½v₂² = ½v₁² + GM(1/r₂ − 1/r₁): v₂ = √(2000² + 2 × 3.98 × 10¹⁴ × (1 ÷ 1.0 × 10⁷ − 1 ÷ 1.0 × 10⁸)) = 8700 m s⁻¹. Mark scheme (4 marks). C1: energy conservation per unit mass. C1: Ep change. C1: rearranged for v₂. A1: v = 8700 m s⁻¹.', 4, NULL, NULL),
('6e64259a-f564-5d68-98a6-0eeb81c90c2b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 39, 39, 'Two satellites of mass m and 2m orbit at the same radius. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The heavier satellite has twice the gravitational potential energy (twice as negative) but the same speed', NULL, false, NULL, false, NULL, 'Ep = −GMm/r ∝ m, so the 2m satellite''s Ep is twice as negative. The orbital speed √(GM/r) is independent of the satellite''s mass. Mark scheme (3 marks). C1: Ep ∝ m. C1: speed independent of m. A1: C (The heavier satellite has twice the gravitational potential energy (twice as negative) but the same speed).', 3, NULL, NULL),
('640560bc-c4f7-5cda-a9b0-48dedbf6aa40', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 40, 40, 'A rock of mass 4.0 kg rests on the surface of an asteroid of mass 8.0 × 10¹⁶ kg and radius 2.0 km. Calculate the minimum energy needed to remove the rock to infinity. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '10672', 'J', false, NULL, false, NULL, 'E = GMm/R = 6.67 × 10⁻¹¹ × 8.0 × 10¹⁶ × 4.0 ÷ 2000 = 1.07 × 10⁴ J. Mark scheme (3 marks). C1: energy needed = −Ep at surface. C1: GMm/R with R in m. A1: E = 1.07 × 10⁴ J.', 3, NULL, NULL),
('2f7b7cbe-c97c-5c56-ab68-4d9e86d62ba9', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 41, 41, 'A 15 000 kg rocket rises from the Earth''s surface to a height of 250 km. Calculate the increase in its gravitational potential energy, using Ep = −GMm/r. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '3.541e10', 'J', false, NULL, false, NULL, 'ΔEp = GMm(1/R − 1/r) = 3.98 × 10¹⁴ × 15000 × (1 ÷ 6.37 × 10⁶ − 1 ÷ 6.62 × 10⁶) = 3.54 × 10¹⁰ J. Mark scheme (3 marks). C1: r = R + h. C1: ΔEp = GMm(1/r₁ − 1/r₂). C1: substitution.', 3, NULL, NULL),
('a86d0cdf-8553-5208-9b65-d8855e2b0e0e', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 42, 42, 'A probe is launched from the Earth''s surface at 15 km s⁻¹ (greater than the escape speed, 11.2 km s⁻¹). Ignoring other bodies and air, what is its speed a very long way from the Earth?', NULL, 2, 'multiple_choice'::answer_type, 'About 10 km s⁻¹', NULL, false, NULL, false, NULL, '½v∞² = ½v₀² − ½v_esc², so v∞ = √(15² − 11.2²) = √(225 − 125) ≈ 10 km s⁻¹. Mark scheme (3 marks). C1: energy conservation. C1: v∞² = v₀² − v_esc². A1: A (About 10 km s⁻¹).', 3, NULL, NULL),
('b45c437d-b11d-5107-97eb-3a7d92fd6f4a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 43, 43, 'A 1500 kg satellite is moved from a circular orbit of radius 7.0 × 10⁶ m to one of radius 4.2 × 10⁷ m. For a circular orbit Ek = GMm/2r. (a) Calculate the change in gravitational potential energy. (b) Calculate the change in kinetic energy. (c) Calculate the energy the rocket motors must supply (ignore losses). Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '3.555e10', 'J', false, NULL, false, NULL, '(a) ΔEp = GMm(1/r₁ − 1/r₂) = 3.98 × 10¹⁴ × 1500 × (1 ÷ 7.0 × 10⁶ − 1 ÷ 4.2 × 10⁷) = 7.11 × 10¹⁰ J. (b) ΔEk = (GMm/2)(1/r₂ − 1/r₁) = −½ΔEp = −3.56 × 10¹⁰ J. (c) energy supplied = ΔEp + ΔEk = 7.111 × 10¹⁰ + (−3.555 × 10¹⁰) = 3.56 × 10¹⁰ J. Mark scheme (6 marks). C1: ΔEp formula. A1: ΔEp. C1: ΔEk = −½ΔEp. A1: ΔEk. C1: total = ΔEp + ΔEk. A1: E = 3.56 × 10¹⁰ J.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fg29ebf838-t fg29ebf838-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg29ebf838-t">Changing orbit</title><desc id="fg29ebf838-d">The Earth and two circular orbits drawn to scale: the inner orbit of radius 7.0 × 10⁶ m and the outer orbit of radius 4.2 × 10⁷ m.</desc><circle cx="180" cy="160" r="19.1" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="180" cy="160" r="21" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="184.5" y="137.8" width="12" height="8" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="202.5" y="129.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">7.0 × 10⁶ m</text><circle cx="180" cy="160" r="126" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><rect x="185" y="30.5" width="12" height="8" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="203" y="22.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">4.2 × 10⁷ m</text></svg>', 'The Earth and two circular orbits drawn to scale: the inner orbit of radius 7.0 × 10⁶ m and the outer orbit of radius 4.2 × 10⁷ m.'),
('cf2e9932-c31b-5a1e-8452-21a33107a2a4', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 44, 44, 'Jupiter has mass 1.90 × 10²⁷ kg and radius 7.0 × 10⁷ m. (a) Calculate the escape speed from Jupiter. (b) Compare it with the escape speed from the Earth (11.2 km s⁻¹). (c) Use energy ideas to explain why Jupiter has kept hydrogen in its atmosphere but the Earth has not. Give only the answer to (a). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '60174', 'm s⁻¹', false, NULL, false, NULL, '(a) v = √(2GM/R) = √(2 × 6.67 × 10⁻¹¹ × 1.90 × 10²⁷ ÷ 7.0 × 10⁷) = 6.02 × 10⁴ m s⁻¹. (b) About 5.4 times the Earth''s. (c) Light hydrogen molecules move fastest at a given temperature; on Earth a significant fraction exceeds 11 km s⁻¹ over geological time, but almost none reach Jupiter''s much higher escape speed (and Jupiter is colder). Mark scheme (5 marks). C1: v = √(2GM/R). A1: v_esc = 6.02 × 10⁴ m s⁻¹. B1: comparison. B1: molecular speeds vs escape speed. B1: lighter molecules faster.', 5, NULL, NULL),
('88ea5499-ad04-519b-b7e0-ae3c4ab119b9', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 45, 45, 'A projectile is fired vertically upwards from the Earth''s surface at 5.0 km s⁻¹. Ignore air resistance and the Earth''s rotation. (a) Explain why ½mv² = mgh would give the wrong maximum height. (b) Use Ep = −GMm/r to find the distance from the Earth''s centre at which it stops. (c) Calculate the maximum height above the surface. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '1.592e6', 'm', false, NULL, false, NULL, '(a) The height is a large fraction of R, so g is not constant. (b) ½v² − GM/R = −GM/r: 1/r = 1/R − v²/(2GM) = 1 ÷ 6.37 × 10⁶ − 5000² ÷ (2 × 3.98 × 10¹⁴) = 1.256 × 10⁻⁷ m⁻¹, r = 7.96 × 10⁶ m. (c) h = r − R = 7.962 × 10⁶ − 6.37 × 10⁶ = 1.59 × 10⁶ m. Mark scheme (6 marks). B1: g not uniform over this distance. C1: energy conservation with −GMm/r. M1: rearranged for 1/r. A1: r. C1: h = r − R. A1: h = 1.59 × 10⁶ m.', 6, NULL, NULL),
('8bfc7bf8-14d1-5187-b200-1beae319a195', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 46, 46, 'A black hole is an object whose escape speed is at least the speed of light. (a) Show that the radius R of a black hole of mass M is 2GM/c². (b) Calculate R for a black hole with the mass of the Sun, 1.99 × 10³⁰ kg. (c) Comment on whether a Newtonian argument is really valid here. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻² and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '2950', 'm', false, NULL, false, NULL, '(a) √(2GM/R) = c gives R = 2GM/c². (b) R = 2 × 6.67 × 10⁻¹¹ × 1.99 × 10³⁰ ÷ (3.00 × 10⁸)² = 2950 m (about 3 km). (c) It is not: at speeds near c relativity is needed, although the result happens to match general relativity. Mark scheme (5 marks). M1: escape speed = c. A1: R = 2GM/c². C1: substitution. A1: R = 2950 m. B1: relativity needed.', 5, NULL, NULL),
('03ef7508-3488-515b-90f0-5f2e01eeccea', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 47, 47, 'An astronaut on the International Space Station (orbit radius 6.77 × 10⁶ m, speed 7.66 km s⁻¹) throws a 0.50 kg tool. (a) Calculate the tool''s kinetic energy in the orbit. (b) Calculate its gravitational potential energy. (c) Calculate its total energy and explain the sign. Give only the total energy in (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '-1.474e7', 'J', false, NULL, true, NULL, '(a) Ek = ½mv² = 0.5 × 0.50 × 7660² = 1.47 × 10⁷ J. (b) Ep = −GMm/r = −3.98 × 10¹⁴ × 0.50 ÷ 6.77 × 10⁶ = −2.94 × 10⁷ J. (c) E = 1.467 × 10⁷ + (−2.941 × 10⁷) = −1.47 × 10⁷ J. It is negative: the tool is bound to the Earth; energy would be needed to escape. Mark scheme (6 marks). C1: Ek = ½mv². A1: Ek. C1: Ep = −GMm/r. A1: E = −1.47 × 10⁷ J. C1: total. B1: negative means bound.', 6, NULL, NULL),
('3262bd78-a6db-5268-b901-e34b9f493aec', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 48, 48, 'A 2000 kg spacecraft coasts from a distance of 4.0 × 10⁸ m from the Earth''s centre towards the Earth, starting at 1.0 km s⁻¹. Ignore the Moon. (a) Calculate its gravitational potential energy at the start. (b) Calculate the speed it would have at 1.0 × 10⁸ m from the Earth''s centre. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '2641', 'm s⁻¹', false, NULL, false, NULL, '(a) Ep = −GMm/r = −3.98 × 10¹⁴ × 2000 ÷ 4.0 × 10⁸ = −1.99 × 10⁹ J. (b) ½v² = ½(1000)² + GM(1/r₂ − 1/r₁): v = √(1000² + 2 × 3.98 × 10¹⁴ × (1 ÷ 1.0 × 10⁸ − 1 ÷ 4.0 × 10⁸)) = 2640 m s⁻¹. Mark scheme (5 marks). C1: Ep = −GMm/r. A1: Ep. C1: energy conservation. C1: Ep difference. A1: v = 2640 m s⁻¹.', 5, NULL, NULL),
('8a53aa2e-0253-529f-8dbe-14572043edde', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 49, 49, 'A graph of the gravitational potential energy Ep of a 1.0 kg mass against distance r from the centre of a planet is a curve. Readings: r = 1.0 × 10⁷ m, Ep = −4.0 × 10⁷ J; r = 2.0 × 10⁷ m, Ep = −2.0 × 10⁷ J. (a) Show that the readings fit Ep ∝ −1/r. (b) Determine GM for the planet. (c) The gradient of the Ep–r graph equals the force on the mass. Calculate the force at r = 2.0 × 10⁷ m. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1', 'N', false, NULL, false, NULL, '(a) Ep × r = −4.0 × 10¹⁴ J m for both, so Ep ∝ −1/r. (b) Ep = −GMm/r with m = 1.0 kg: GM = 4.0 × 10¹⁴ N m² kg⁻¹. (c) F = dEp/dr = GMm/r² = 4.0 × 10¹⁴ ÷ (2.0 × 10⁷)² = 1.00 N (towards the planet). Mark scheme (6 marks). M1: Ep × r constant. A1: Ep ∝ −1/r. C1: GM from Ep r. A1: GM. M1: F = GMm/r² from gradient. A1: F = 1.0 N.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg81de8875-t fg81de8875-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg81de8875-t">Potential energy against distance</title><desc id="fg81de8875-d">Graph of the gravitational potential energy of a 1.0 kg mass against distance from the planet''s centre: the values are negative and approach zero as r increases.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="34" x2="100" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170.5" y1="34" x2="170.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="241" y1="34" x2="241" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="311.5" y1="34" x2="311.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="218.9" x2="382" y2="218.9" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="172.7" x2="382" y2="172.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="126.4" x2="382" y2="126.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="80.2" x2="382" y2="80.2" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="388" y2="34" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,34 385.7,37 385.7,31" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="34" x2="29.4" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="100" y1="34" x2="100" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="100" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="170.5" y1="34" x2="170.5" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="170.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="241" y1="34" x2="241" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="241" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="311.5" y1="34" x2="311.5" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="311.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="382" y1="34" x2="382" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5</text><line x1="25.4" y1="218.9" x2="29.4" y2="218.9" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="218.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−4</text><line x1="25.4" y1="172.7" x2="29.4" y2="172.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="172.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−3</text><line x1="25.4" y1="126.4" x2="29.4" y2="126.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="126.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−2</text><line x1="25.4" y1="80.2" x2="29.4" y2="80.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="80.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−1</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r / 10⁷ m</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">Ep / 10⁷ J</text><line x1="96" y1="214.9" x2="104" y2="222.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="96" y1="222.9" x2="104" y2="214.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="166.5" y1="122.4" x2="174.5" y2="130.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="166.5" y1="130.4" x2="174.5" y2="122.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Graph of the gravitational potential energy of a 1.0 kg mass against distance from the planet''s centre: the values are negative and approach zero as r increases.'),
('6ba0a2a5-2752-5fff-860e-8f7817fbcb5b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '3dbf9699-434d-4abd-93a9-3d272b99c33d', 'a-level', '17.3', '9702 coursebook 17.3 · Energy in a gravitational field', 50, 50, 'A space elevator lifts a 1000 kg capsule from the Earth''s surface to geostationary height (orbit radius 4.22 × 10⁷ m). (a) Calculate the gain in gravitational potential energy. (b) Explain why mgh with g = 9.81 N kg⁻¹ would give a very wrong answer. (c) The capsule must also move at 3.07 km s⁻¹ at the top. Calculate the kinetic energy it needs there. Give only the answer to (a). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '5.308e10', 'J', false, NULL, false, NULL, '(a) ΔEp = GMm(1/R − 1/r) = 3.98 × 10¹⁴ × 1000 × (1 ÷ 6.37 × 10⁶ − 1 ÷ 4.22 × 10⁷) = 5.31 × 10¹⁰ J. (b) g falls to about 0.22 N kg⁻¹ at the top, so mgh would greatly overestimate (by about 4.5 times). (c) Ek = ½mv² = 0.5 × 1000 × 3070² = 4.71 × 10⁹ J. Mark scheme (5 marks). C1: ΔEp formula. A1: ΔEp. B1: g not uniform. C1: Ek = ½mv². A1: ΔEp = 5.31 × 10¹⁰ J.', 5, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('6695376a-48dd-541a-bd1f-d42ef9be212b', '33cd3405-1379-5459-ab88-17067a0e949e', 'The rocket is moving too fast', 'A', false, 0),
('13dcba36-151e-5db1-9613-8f29ff6793e2', '33cd3405-1379-5459-ab88-17067a0e949e', 'mgΔh only applies to objects at rest', 'B', false, 1),
('3a3a05ad-30b3-5eee-9a51-4acfdf42776f', '33cd3405-1379-5459-ab88-17067a0e949e', 'g is almost constant over a few metres but falls significantly over thousands of kilometres', 'C', true, 2),
('9461ef8c-7852-5d26-b845-b04de9a43d8d', '33cd3405-1379-5459-ab88-17067a0e949e', 'Rockets are not affected by gravity', 'D', false, 3),
('c3fdc5c7-3fac-54cd-93f7-1eccd245daad', '301e0c45-a921-553a-982e-58199fcc2320', 'At an infinite distance from the mass', 'A', true, 0),
('ba58c0a1-e2f2-5a69-a942-5a3a0f063d8b', '301e0c45-a921-553a-982e-58199fcc2320', 'At the surface of the Earth', 'B', false, 1),
('73cf9119-f9aa-5894-9db1-7222ac425e1a', '301e0c45-a921-553a-982e-58199fcc2320', 'At the centre of the Earth', 'C', false, 2),
('374141e3-c1c0-56a3-b31b-7af713ec2c4e', '301e0c45-a921-553a-982e-58199fcc2320', 'At the height of a geostationary orbit', 'D', false, 3),
('3a598204-4f9e-5449-bf7d-ba9f50348f7c', 'b68f5d3b-f55b-5a00-83fd-1a2a54b87d7b', 'It decreases (becomes more negative)', 'A', false, 0),
('3e6e1340-268f-5cd1-a940-d6346b206b96', 'b68f5d3b-f55b-5a00-83fd-1a2a54b87d7b', 'It stays the same', 'B', false, 1),
('c9987a3c-231f-52d2-98cf-58533e47f7e8', 'b68f5d3b-f55b-5a00-83fd-1a2a54b87d7b', 'It becomes positive', 'C', false, 2),
('5a30a5bb-75f5-5061-9e52-557044c07efb', 'b68f5d3b-f55b-5a00-83fd-1a2a54b87d7b', 'It increases (becomes less negative)', 'D', true, 3),
('fd8d5970-7850-5ee1-8c9d-12bc4489be49', '00687bb5-3c0c-5a0b-9444-d64070cf1935', 'The gravitational field strength at the point', 'A', false, 0),
('34c50779-7a48-52ad-8815-d552defa7670', '00687bb5-3c0c-5a0b-9444-d64070cf1935', 'The gravitational potential at the point', 'B', true, 1),
('11c7e552-9b36-5e52-b70c-ec7544cfe008', '00687bb5-3c0c-5a0b-9444-d64070cf1935', 'The gravitational potential energy of the mass', 'C', false, 2),
('97d79719-43fd-54f0-94c7-c0a59a43a29c', '00687bb5-3c0c-5a0b-9444-d64070cf1935', 'The escape speed from the point', 'D', false, 3),
('cac4e374-4e23-5f99-80b4-d1f33f5f2432', 'c7df0060-4afd-5571-9335-41447117a339', 'Gravity is a repulsive force', 'A', false, 0),
('23e612f9-6fb9-5e9a-818f-e8d9a70204be', 'c7df0060-4afd-5571-9335-41447117a339', 'The mass has negative mass', 'B', false, 1),
('04318158-0822-5305-904e-31aa81eaef9d', 'c7df0060-4afd-5571-9335-41447117a339', 'Work must be done on a mass to move it out to infinity, where Ep is zero', 'C', true, 2),
('c514a62f-7821-5ad7-b655-b765e1d1880e', 'c7df0060-4afd-5571-9335-41447117a339', 'Kinetic energy is always positive so Ep must be negative', 'D', false, 3),
('b607d4e1-b5a4-52c9-80f0-ef90923e6f12', 'f3f87a40-b9da-5210-ac10-eee2866ed01e', 'Ep becomes more negative and Ek increases by the same amount', 'A', true, 0),
('3cae8077-5263-5cab-9b26-5bfac3dc3509', 'f3f87a40-b9da-5210-ac10-eee2866ed01e', 'Ep becomes less negative and Ek increases', 'B', false, 1),
('18c7d7be-4878-5139-b89c-4987bd41b1f6', 'f3f87a40-b9da-5210-ac10-eee2866ed01e', 'Ep and Ek both increase', 'C', false, 2),
('ab88e83d-7a21-57ae-ae1d-9d08360981c9', 'f3f87a40-b9da-5210-ac10-eee2866ed01e', 'Ep stays constant and Ek increases', 'D', false, 3),
('43358166-59ed-5fc7-bc51-167f0523003b', '58ecfb5e-f0de-54ec-8741-95f9be6aac18', 'v = √(GM/R)', 'A', false, 0),
('7342f5e9-3143-5284-a900-e90309e24ba3', '58ecfb5e-f0de-54ec-8741-95f9be6aac18', 'v = 2GM/R', 'B', false, 1),
('73152f4b-93bd-5469-868f-4c18201620f4', '58ecfb5e-f0de-54ec-8741-95f9be6aac18', 'v = √(GM/R²)', 'C', false, 2),
('0a1fe3c7-df74-5a7d-bf7e-73adcf215d4b', '58ecfb5e-f0de-54ec-8741-95f9be6aac18', 'v = √(2GM/R)', 'D', true, 3),
('85f821bc-34ca-5c53-8ccd-97ddc1a33a86', '8f7c48f9-d9dc-51cf-b363-ab6854e3e6eb', 'Yes: heavier objects need a higher speed', 'A', false, 0),
('7d8328c0-4ae0-55c9-a45e-71d8f762a3e1', '8f7c48f9-d9dc-51cf-b363-ab6854e3e6eb', 'No: both ½mv² and GMm/R are proportional to m, so m cancels', 'B', true, 1),
('38980e22-5dc5-58a5-a05c-344f5a8285a4', '8f7c48f9-d9dc-51cf-b363-ab6854e3e6eb', 'Yes: lighter objects need a higher speed', 'C', false, 2),
('d2cdbf80-6cd6-5d67-ab38-b44c1b116183', '8f7c48f9-d9dc-51cf-b363-ab6854e3e6eb', 'No: escape speed depends only on the launch angle', 'D', false, 3),
('35bf5ef5-1a72-50f1-8637-288dc4aa2728', '9f95c57b-eb2f-5224-9439-de4ce29dff3c', 'It doubles, from −X to −2X', 'A', false, 0),
('0fa4fb92-469f-5cc3-aaa1-11e95eb76e7e', '9f95c57b-eb2f-5224-9439-de4ce29dff3c', 'It quarters', 'B', false, 1),
('fe25b6c9-6453-5648-a345-261f96109250', '9f95c57b-eb2f-5224-9439-de4ce29dff3c', 'It doubles in value but halves in size, i.e. from −X to −X/2', 'C', true, 2),
('5cbfab0f-d3d5-5a67-8472-a283c08c1c94', '9f95c57b-eb2f-5224-9439-de4ce29dff3c', 'It does not change', 'D', false, 3),
('e28195b5-7e6c-5466-b91b-ed21141298e8', 'dc84da64-ab0a-529d-add7-761193d5d197', 'It keeps moving away, slowing down, and its speed approaches zero as it approaches infinity', 'A', true, 0),
('6b16db75-aaa6-5fd6-8927-00c6d101f7eb', 'dc84da64-ab0a-529d-add7-761193d5d197', 'It falls back to the Earth', 'B', false, 1),
('db90c247-3034-5097-8cc7-f2999e06a202', 'dc84da64-ab0a-529d-add7-761193d5d197', 'It moves away at constant speed', 'C', false, 2),
('063b7732-a452-5bab-a8b4-bc7427f37d2e', 'dc84da64-ab0a-529d-add7-761193d5d197', 'It goes into a circular orbit', 'D', false, 3),
('ac38784b-c0c4-5880-89af-b4683b4a4ac5', 'd830efcc-13c8-58a3-ba19-e1c39c1e1129', 'There is no gravity in orbit', 'A', false, 0),
('5bfccf10-c634-5cf4-a52c-83fce247dd09', 'd830efcc-13c8-58a3-ba19-e1c39c1e1129', 'Its engines run continuously at a low level', 'B', false, 1),
('fa172a74-b768-5bcd-a764-fb2838651853', 'd830efcc-13c8-58a3-ba19-e1c39c1e1129', 'Its potential energy is zero in orbit', 'C', false, 2),
('c10ac6f0-8f27-5b71-aa8c-5f428c2a41c9', 'd830efcc-13c8-58a3-ba19-e1c39c1e1129', 'Gravity is perpendicular to its velocity, so it does no work and the kinetic energy is constant', 'D', true, 3),
('0b397f03-7ddb-5b43-b492-1937d4cfc359', '4f9d8cd1-057b-5608-8151-4cfd168539c1', '√(GM/R)', 'A', false, 0),
('f64e8918-a4af-52ff-b987-b17c5bc0472f', '4f9d8cd1-057b-5608-8151-4cfd168539c1', '√(2GM/R)', 'B', true, 1),
('aa8909cc-56c3-5c85-b869-0861cd55a74b', '4f9d8cd1-057b-5608-8151-4cfd168539c1', '2GM/R', 'C', false, 2),
('029863a8-65c7-5309-9b4b-a72a224b5cff', '4f9d8cd1-057b-5608-8151-4cfd168539c1', '√(2GMR)', 'D', false, 3),
('13b6bbcc-3614-5823-8d52-e5007ca9d9b9', '6e64259a-f564-5d68-98a6-0eeb81c90c2b', 'Both have the same potential energy', 'A', false, 0),
('a8d46c08-717d-538a-a50c-952f9128bb17', '6e64259a-f564-5d68-98a6-0eeb81c90c2b', 'The heavier one moves twice as fast', 'B', false, 1),
('ed1d62cc-b519-5822-aa96-4cabe14045d9', '6e64259a-f564-5d68-98a6-0eeb81c90c2b', 'The heavier satellite has twice the gravitational potential energy (twice as negative) but the same speed', 'C', true, 2),
('7207bace-c459-5b37-af16-2aaede38d552', '6e64259a-f564-5d68-98a6-0eeb81c90c2b', 'The heavier one has half the potential energy', 'D', false, 3),
('db2a37a2-d530-5fa3-ad37-845c5fbcfaa2', 'a86d0cdf-8553-5208-9b65-d8855e2b0e0e', 'About 10 km s⁻¹', 'A', true, 0),
('69eae89d-ac81-5c90-afdf-42f098065a98', 'a86d0cdf-8553-5208-9b65-d8855e2b0e0e', 'Zero', 'B', false, 1),
('b73cb117-77f3-5d7a-bd1c-a2d571bf5987', 'a86d0cdf-8553-5208-9b65-d8855e2b0e0e', '15 km s⁻¹', 'C', false, 2),
('f6bc19f6-cd03-5a98-9206-de6f8d09e3fb', 'a86d0cdf-8553-5208-9b65-d8855e2b0e0e', '3.8 km s⁻¹', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('953513da-32e3-5b24-b1c5-eb4e58bfe3cb', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 14, 14, 'Calculate the gravitational potential at the surface of the Earth. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '-6.251e7', 'J kg⁻¹', false, NULL, true, NULL, 'φ = −GM/r = −6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ 6.37 × 10⁶ = −6.25 × 10⁷ J kg⁻¹. Mark scheme (2 marks). C1: φ = −GM/r. A1: φ = −6.25 × 10⁷ J kg⁻¹.', 2, NULL, NULL),
('26d81418-af96-5170-be69-9a9feffae6ad', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 15, 15, 'Calculate the gravitational potential at the surface of the Moon (mass 7.35 × 10²² kg, radius 1.74 × 10⁶ m). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '-2.817e6', 'J kg⁻¹', false, NULL, true, NULL, 'φ = −GM/R = −6.67 × 10⁻¹¹ × 7.35 × 10²² ÷ 1.74 × 10⁶ = −2.82 × 10⁶ J kg⁻¹. Mark scheme (2 marks). C1: φ = −GM/R. A1: φ = −2.82 × 10⁶ J kg⁻¹.', 2, NULL, NULL),
('9ee9e0f9-06b8-5fa5-a775-2c6de579ad1d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 16, 16, 'Define gravitational potential at a point.', NULL, 1, 'multiple_choice'::answer_type, 'The work done per unit mass in bringing a small test mass from infinity to that point', NULL, false, NULL, false, NULL, 'φ = W/m for a test mass brought from infinity. Because gravity is attractive, the work done by an external agent is negative, so φ < 0. Mark scheme (1 mark). B1: C (The work done per unit mass in bringing a small test mass from infinity to that point).', 1, NULL, NULL),
('5f1ff724-7a0f-58c6-bbe6-6e932852fe23', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 17, 17, 'What is the unit of gravitational potential?', NULL, 1, 'multiple_choice'::answer_type, 'J kg⁻¹', NULL, false, NULL, false, NULL, 'Potential is work (J) per unit mass (kg): J kg⁻¹. Mark scheme (1 mark). B1: A (J kg⁻¹).', 1, NULL, NULL),
('e1ad5319-4bb5-5ae8-a1c8-55198599c1e3', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 18, 18, 'How does the gravitational potential change as you move away from the Earth towards infinity?', NULL, 1, 'multiple_choice'::answer_type, 'It increases from a negative value towards zero', NULL, false, NULL, false, NULL, 'φ = −GM/r. As r increases, φ becomes less negative and approaches zero at infinity. Mark scheme (1 mark). B1: D (It increases from a negative value towards zero).', 1, NULL, NULL),
('213802e5-9e5c-509b-b514-2fbe1b6c0793', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 19, 19, 'A 5.0 kg mass is at a point where the gravitational potential is −3.6 × 10⁷ J kg⁻¹. Calculate its gravitational potential energy.', NULL, 1, 'numeric'::answer_type, '-1.8e8', 'J', false, NULL, true, NULL, 'Ep = mφ = 5.0 × (−3.6 × 10⁷) = −1.8 × 10⁸ J. Mark scheme (2 marks). C1: Ep = mφ. A1: Ep = −1.8 × 10⁸ J.', 2, NULL, NULL),
('ecdf9fa1-3c2c-52ff-b3fb-22d26a1a7624', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 20, 20, 'The gravitational potential at point A is −6.0 × 10⁷ J kg⁻¹ and at point B is −2.0 × 10⁷ J kg⁻¹. Calculate the work done to move a 1.0 kg mass from A to B.', NULL, 1, 'numeric'::answer_type, '4e7', 'J', false, NULL, false, NULL, 'W = mΔφ = 1.0 × (−2.0 × 10⁷ − (−6.0 × 10⁷)) = 4.0 × 10⁷ J. Mark scheme (2 marks). C1: W = mΔφ. A1: W = 4.0 × 10⁷ J.', 2, NULL, NULL),
('79c9e6ff-b558-5b67-ba81-4f36458dbabe', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 21, 21, 'What is an equipotential surface in a gravitational field?', NULL, 1, 'multiple_choice'::answer_type, 'A surface on which every point has the same gravitational potential', NULL, false, NULL, false, NULL, 'On an equipotential no work is done moving a mass along it. Around a spherical planet the equipotentials are concentric spheres, perpendicular to the field lines. Mark scheme (1 mark). B1: B (A surface on which every point has the same gravitational potential).', 1, NULL, NULL),
('e2352474-56a7-5e1a-8e6c-6d7cea37e62b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 22, 22, 'How are equipotentials and gravitational field lines oriented relative to each other?', NULL, 1, 'multiple_choice'::answer_type, 'They are always perpendicular', NULL, false, NULL, false, NULL, 'No work is done moving along an equipotential, so there is no component of the field along it: field lines cross equipotentials at 90°. Mark scheme (1 mark). B1: C (They are always perpendicular).', 1, NULL, NULL),
('d2a6a380-f746-53c3-83bb-417f6dd7a9b8', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 23, 23, 'Find the gravitational potential at a distance of 4.22 × 10⁷ m from the Earth''s centre (geostationary orbit). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '-9.436e6', 'J kg⁻¹', false, NULL, true, NULL, 'φ = −GM/r = −6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ 4.22 × 10⁷ = −9.44 × 10⁶ J kg⁻¹. Mark scheme (2 marks). C1: φ = −GM/r. A1: φ = −9.44 × 10⁶ J kg⁻¹.', 2, NULL, NULL),
('decadf2d-b4ef-54c1-b4d4-bbad57b4ecbf', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 24, 24, 'The gravitational potential at distance r from a point mass is φ. What is it at distance 3r?', NULL, 1, 'multiple_choice'::answer_type, 'φ/3', NULL, false, NULL, false, NULL, 'φ = −GM/r ∝ 1/r. At 3r it is one third of φ (still negative, closer to zero). Mark scheme (1 mark). B1: A (φ/3).', 1, NULL, NULL),
('d70191f0-af2e-521d-91f0-06dae05f3af9', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 25, 25, 'Jupiter (mass 1.90 × 10²⁷ kg) has radius 7.0 × 10⁷ m. Calculate the gravitational potential at its cloud tops. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '-1.81e9', 'J kg⁻¹', false, NULL, true, NULL, 'φ = −GM/R = −6.67 × 10⁻¹¹ × 1.90 × 10²⁷ ÷ 7.0 × 10⁷ = −1.81 × 10⁹ J kg⁻¹. Mark scheme (2 marks). C1: φ = −GM/R. A1: φ = −1.81 × 10⁹ J kg⁻¹.', 2, NULL, NULL),
('9645d7bf-a26a-5e26-b0f1-6272d71b6308', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 26, 26, 'Gravitational potential is a scalar. What does this mean when combining the potentials due to two planets at a point?', NULL, 1, 'multiple_choice'::answer_type, 'The potentials simply add as numbers', NULL, false, NULL, false, NULL, 'Potential has no direction. The total potential is the algebraic sum: φ = −GM₁/r₁ − GM₂/r₂. Mark scheme (1 mark). B1: D (The potentials simply add as numbers).', 1, NULL, NULL),
('15c65c28-08f9-5e85-b328-a92165cde985', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 27, 27, 'Which of these is equal to the gravitational field strength at a point?', NULL, 1, 'multiple_choice'::answer_type, 'Minus the potential gradient, −dφ/dr', NULL, false, NULL, false, NULL, 'g = −dφ/dr: the field points down the potential gradient, towards lower (more negative) potential. Mark scheme (1 mark). B1: B (Minus the potential gradient, −dφ/dr).', 1, NULL, NULL),
('88f57796-d131-5c90-a0c3-2b571b0ab9a8', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 28, 28, 'A 70 kg astronaut stands on Mars, where the gravitational potential is −1.26 × 10⁷ J kg⁻¹. Calculate the astronaut''s gravitational potential energy.', NULL, 1, 'numeric'::answer_type, '-8.82e8', 'J', false, NULL, true, NULL, 'Ep = mφ = 70 × (−1.26 × 10⁷) = −8.82 × 10⁸ J. Mark scheme (2 marks). C1: Ep = mφ. A1: Ep = −8.82 × 10⁸ J.', 2, NULL, NULL),
('ab9285f3-f19c-5dce-adca-8c899198d974', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 29, 29, 'At which point is the gravitational potential due to the Earth greatest (least negative)?', NULL, 1, 'multiple_choice'::answer_type, 'At a point a long way from the Earth', NULL, false, NULL, false, NULL, 'φ = −GM/r rises towards zero as r increases, so it is greatest far away. Mark scheme (1 mark). B1: C (At a point a long way from the Earth).', 1, NULL, NULL),
('23e12314-230b-58bc-b4c1-c95591f91c8c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 30, 30, 'Calculate the gravitational potential due to the Sun at the Earth''s orbit, 1.50 × 10¹¹ m away. Sun''s mass = 1.99 × 10³⁰ kg. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '-8.849e8', 'J kg⁻¹', false, NULL, true, NULL, 'φ = −GM/r = −6.67 × 10⁻¹¹ × 1.99 × 10³⁰ ÷ 1.50 × 10¹¹ = −8.85 × 10⁸ J kg⁻¹. Mark scheme (2 marks). C1: φ = −GM/r. A1: φ = −8.85 × 10⁸ J kg⁻¹.', 2, NULL, NULL),
('025843c7-e5cb-5e0f-9d0b-81a6957f7051', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 31, 31, 'Calculate the change in gravitational potential between the Earth''s surface and a point 2000 km above it. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '1.494e7', 'J kg⁻¹', false, NULL, false, NULL, 'φ₁ = −GM/R = −6.25 × 10⁷ J kg⁻¹, φ₂ = −GM/(R + h) = −3.98 × 10¹⁴ ÷ 8.37 × 10⁶ = −4.76 × 10⁷ J kg⁻¹. Δφ = −4.757 × 10⁷ − (−6.251 × 10⁷) = 1.49 × 10⁷ J kg⁻¹. Mark scheme (3 marks). C1: φ at each point. C1: r = R + h. C1: Δφ = φ₂ − φ₁.', 3, NULL, NULL),
('49487d7b-c16f-540e-86e8-2e12a844eef5', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 32, 32, 'A 50 kg payload is raised through a gravitational potential difference of 3.5 × 10⁶ J kg⁻¹. Calculate the energy needed, and explain why it does not matter which path is taken.', NULL, 2, 'numeric'::answer_type, '1.75e8', 'J', false, NULL, false, NULL, 'W = mΔφ = 50 × 3.5 × 10⁶ = 1.75 × 10⁸ J. Potential depends only on position, so the work done against gravity depends only on the start and end points. Mark scheme (3 marks). C1: W = mΔφ. B1: path independent. A1: W = 1.75 × 10⁸ J.', 3, NULL, NULL),
('68714250-b43e-59c6-b713-9f69569154ab', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 33, 33, 'Calculate the total gravitational potential at the point 3.46 × 10⁸ m from the Earth''s centre on the line to the Moon (3.84 × 10⁸ m away). Moon''s mass = 7.35 × 10²² kg. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '-1.28e6', 'J kg⁻¹', false, NULL, true, NULL, 'φ = −GM_E/r_E − GM_M/r_M = −3.98 × 10¹⁴ ÷ 3.46 × 10⁸ − 6.67 × 10⁻¹¹ × 7.35 × 10²² ÷ 3.8 × 10⁷ = −1.28 × 10⁶ J kg⁻¹. Mark scheme (4 marks). C1: potentials add as scalars. C1: distance from Moon 3.8 × 10⁷ m. C1: substitution. A1: φ = −1.28 × 10⁶ J kg⁻¹.', 4, NULL, NULL),
('a54c3388-702b-5209-8e5f-4bd58d22c51f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 34, 34, 'The gravitational potential at the surface of a planet is −5.0 × 10⁷ J kg⁻¹. What is the minimum energy needed to remove a 2.0 kg mass from the surface to infinity?', NULL, 2, 'multiple_choice'::answer_type, '1.0 × 10⁸ J', NULL, false, NULL, false, NULL, 'W = mΔφ = 2.0 × (0 − (−5.0 × 10⁷)) = 1.0 × 10⁸ J. The energy supplied is positive. Mark scheme (3 marks). C1: Δφ = 0 − φ. C1: W = mΔφ. A1: A (1.0 × 10⁸ J).', 3, NULL, NULL),
('613cf922-93a3-5759-a78f-39d8e5b38f63', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 35, 35, 'At a distance r from a planet''s centre the gravitational potential is −2.4 × 10⁷ J kg⁻¹ and the field strength is 4.0 N kg⁻¹. Calculate r, using g = −φ/r for a point mass.', NULL, 2, 'numeric'::answer_type, '6e6', 'm', false, NULL, false, NULL, 'φ = −GM/r and g = GM/r², so g = −φ/r and r = −φ/g = 2.4 × 10⁷ ÷ 4.0 = 6.0 × 10⁶ m. Mark scheme (3 marks). C1: g = −φ/r. C1: rearranged. A1: r = 6.0 × 10⁶ m.', 3, NULL, NULL),
('56975624-5ba8-5f4e-8a1b-36eb270726bb', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 36, 36, 'The potential at the surface of a planet of radius 3.0 × 10⁶ m is −1.2 × 10⁷ J kg⁻¹. Calculate the escape speed from the planet.', NULL, 2, 'numeric'::answer_type, '4899', 'm s⁻¹', false, NULL, false, NULL, '½v² = −φ (energy per unit mass needed to reach φ = 0), so v = √(2 × 1.2 × 10⁷) = 4900 m s⁻¹. Mark scheme (4 marks). C1: ½mv² = m|φ|. C1: rearranged. B1: radius not needed. A1: v_esc = 4900 m s⁻¹.', 4, NULL, NULL),
('89326eb9-3aa6-5fd4-8dc3-1c0ec6e6e163', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 37, 37, 'Which graph shape shows how the gravitational potential φ varies with distance r from the centre of a planet, outside the planet?', NULL, 2, 'multiple_choice'::answer_type, 'A curve rising from a large negative value towards zero, getting less steep', NULL, false, NULL, false, NULL, 'φ = −GM/r: negative, approaching zero as r → ∞, with gradient GM/r² (the field strength) decreasing with r. Mark scheme (3 marks). C1: negative values approaching zero. C1: gradient decreases. A1: D (A curve rising from a large negative value towards zero, getting less steep).', 3, NULL, NULL),
('be20f474-1f4b-562c-8595-8285baeea134', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 38, 38, 'A rock falls from rest at a point where φ = −6.0 × 10⁶ J kg⁻¹ to the surface of a moon where φ = −8.5 × 10⁶ J kg⁻¹. There is no atmosphere. Calculate its landing speed.', NULL, 2, 'numeric'::answer_type, '2236', 'm s⁻¹', false, NULL, false, NULL, 'Ek gained per kg = −Δφ = 8.5 × 10⁶ − 6.0 × 10⁶ = 2.5 × 10⁶ J kg⁻¹. ½v² = 2.5 × 10⁶, v = √(2 × 2.5 × 10⁶) = 2240 m s⁻¹. Mark scheme (3 marks). C1: energy per kg = Δφ. C1: ½v² = Δφ. A1: v = 2240 m s⁻¹.', 3, NULL, NULL),
('21e631fe-ed1f-5ad7-a1b2-47cdf97b2301', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 39, 39, 'Two points X and Y are on the same equipotential around the Earth. A satellite moves from X to Y. Which is correct?', NULL, 2, 'multiple_choice'::answer_type, 'No net work is done by gravity, whatever path the satellite takes', NULL, false, NULL, false, NULL, 'Work done by gravity = −mΔφ, and Δφ = 0 between X and Y. Gravity is a conservative field, so this is path independent. Mark scheme (4 marks). C1: Δφ = 0. C1: W = mΔφ. C1: path independence. A1: B (No net work is done by gravity, whatever path the satellite takes).', 4, NULL, NULL),
('0ab7eefd-0a10-5fe8-b9a2-9cc9eb4c65b5', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 40, 40, 'The gravitational potential at a point due to two moons is the sum of their potentials. At point P, moon A gives −4.0 × 10⁶ J kg⁻¹ and moon B gives −2.5 × 10⁶ J kg⁻¹. Calculate the work needed to take a 10 kg probe from P to infinity.', NULL, 2, 'numeric'::answer_type, '6.5e7', 'J', false, NULL, false, NULL, 'Total φ = −4.0 × 10⁶ + (−2.5 × 10⁶) = −6.5 × 10⁶ J kg⁻¹. W = m(0 − φ) = 10 × 6.5 × 10⁶ = 6.5 × 10⁷ J. Mark scheme (3 marks). C1: potentials add. C1: W = −mφ. A1: W = 6.5 × 10⁷ J.', 3, NULL, NULL),
('932d23ab-0e35-5784-b62b-c98e217bc5a2', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '17.4', '9702 coursebook 17.4 · Gravitational potential', 41, 41, 'A gravitational potential–distance graph for a planet has a tangent at r = 1.5 × 10⁷ m with gradient 1.8 J kg⁻¹ m⁻¹. (a) State the field strength there. (b) Calculate GM for the planet. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '4.05e14', 'N m² kg⁻¹', false, NULL, false, NULL, '(a) g = gradient = 1.8 N kg⁻¹ (towards the planet). (b) g = GM/r², so GM = gr² = 1.8 × (1.5 × 10⁷)² = 4.05 × 10¹⁴ N m² kg⁻¹. Mark scheme (4 marks). B1: g = dφ/dr. C1: g = GM/r². C1: GM = gr². A1: GM = 4.05 × 10¹⁴ N m² kg⁻¹.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg5c4e60b2-t fg5c4e60b2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5c4e60b2-t">Potential against distance</title><desc id="fg5c4e60b2-d">Graph of gravitational potential against distance from the planet''s centre, with a dashed tangent at r = 1.5 × 10⁷ m of gradient 1.8 J kg⁻¹ m⁻¹.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="117.6" y1="34" x2="117.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="205.7" y1="34" x2="205.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="293.9" y1="34" x2="293.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="229.8" x2="382" y2="229.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="180.8" x2="382" y2="180.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="131.9" x2="382" y2="131.9" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="82.9" x2="382" y2="82.9" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="388" y2="34" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,34 385.7,37 385.7,31" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="34" x2="29.4" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="117.6" y1="34" x2="117.6" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="117.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="205.7" y1="34" x2="205.7" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="205.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="293.9" y1="34" x2="293.9" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="293.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="382" y1="34" x2="382" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="25.4" y1="229.8" x2="29.4" y2="229.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="229.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−8</text><line x1="25.4" y1="180.8" x2="29.4" y2="180.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="180.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−6</text><line x1="25.4" y1="131.9" x2="29.4" y2="131.9" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="131.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−4</text><line x1="25.4" y1="82.9" x2="29.4" y2="82.9" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="82.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−2</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r / 10⁷ m</text><text x="25.4" y="