('f2a4105c-2cba-57fa-bd02-93bcf468c67a', '74539402-a8c2-5c8a-8d43-a0cca6c45ff6', 'GM/r²', 'C', false, 2),
('1d5ae18f-9eda-5e3a-a332-b3b323ff6a93', '74539402-a8c2-5c8a-8d43-a0cca6c45ff6', '√(GMr)', 'D', false, 3),
('b325e448-0dbd-59b9-9d5c-5a0ff17bb908', '87cec281-8c86-5eb9-9d73-032875736e6a', 'The heavier one is twice as fast', 'A', false, 0),
('de1dc755-bdda-59e1-932d-ad6fd02e5ff3', '87cec281-8c86-5eb9-9d73-032875736e6a', 'The heavier one is half as fast', 'B', false, 1),
('519a0954-cc2c-5b1c-a025-7d8cbb5979fa', '87cec281-8c86-5eb9-9d73-032875736e6a', 'The heavier one is √2 times as fast', 'C', false, 2),
