('3a9b7452-161b-54e5-b1a5-4f77e658b4fe', '71d9b9b5-817a-5a7e-8ce3-19dda0426ba1', '√2', 'D', false, 3),
('8dff3f53-297d-59cb-8147-27e7e537adce', 'b9e42bdf-ee83-5ae7-8ce6-32cc503e8fd6', '−Ek', 'A', false, 0),
