('2ef0528a-1aaf-5c26-a435-aa389997e8c5', 'b9e42bdf-ee83-5ae7-8ce6-32cc503e8fd6', '2Ek', 'C', false, 2),
('8dcb88e9-f1a5-56c5-bdb4-5821382032c9', 'b9e42bdf-ee83-5ae7-8ce6-32cc503e8fd6', '−2Ek', 'D', true, 3),
('e0cf3ccb-f295-5e84-917f-2ee51a4a1087', 'cc6d35ef-cdbf-5fc6-9655-0c5cc5465375', 'v/9', 'A', false, 0),
