INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('c1d9da09-dcaa-59ae-8f67-85863fdeaa93', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 11, 11, 'Calculate the orbital period of a satellite in a circular orbit of radius 8.0 × 10⁶ m around the Earth. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '7125', 's', false, NULL, false, NULL, 'T = 2π√(r³/GM) = 2π × √((8.0 × 10⁶)³ ÷ 3.98 × 10¹⁴) = 7120 s. Mark scheme (2 marks). C1: T² = 4π²r³/GM. A1: T = 7120 s.', 2, NULL, NULL),
('96b232d1-00c3-5ba7-805b-86af9680731d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 12, 12, 'Kepler''s third law for circular orbits around the same central body states that…', NULL, 1, 'multiple_choice'::answer_type, 'T² is proportional to r³', NULL, false, NULL, false, NULL, 'From GMm/r² = mω²r with ω = 2π/T: T² = (4π²/GM) r³, so T² ∝ r³. Mark scheme (1 mark). B1: C (T² is proportional to r³).', 1, NULL, NULL),
('a53ee819-2f80-5124-84b2-7f5a98c07558', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 13, 13, 'Does the orbital period of a satellite in a circular orbit depend on the satellite''s mass?', NULL, 1, 'multiple_choice'::answer_type, 'No — only on the orbit radius and the mass of the central body', NULL, false, NULL, false, NULL, 'T² = 4π²r³/GM: the satellite''s mass cancels out. Mark scheme (1 mark). B1: A (No — only on the orbit radius and the mass of the central body).', 1, NULL, NULL),
('a68e803b-9e3d-5112-8de5-6e2f05454aa8', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 14, 14, 'A moon orbits a planet of mass 6.0 × 10²⁶ kg at a radius of 5.0 × 10⁸ m. Calculate its orbital period. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 1, 'numeric'::answer_type, '3.512e5', 's', false, NULL, false, NULL, 'T = 2π√(r³/GM) = 2π × √((5.0 × 10⁸)³ ÷ (6.67 × 10⁻¹¹ × 6.0 × 10²⁶)) = 3.51 × 10⁵ s. Mark scheme (2 marks). C1: T = 2π√(r³/GM). A1: T = 3.51 × 10⁵ s.', 2, NULL, NULL),
('9263d1a4-ef88-5a42-9da1-caf315977230', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 15, 15, 'Satellite B orbits a planet at four times the radius of satellite A. How many times longer is B''s period?', NULL, 1, 'multiple_choice'::answer_type, '8', NULL, false, NULL, false, NULL, 'T ∝ r^(3/2): 4^(3/2) = 8. Mark scheme (1 mark). B1: D (8).', 1, NULL, NULL),
('a025c435-7cdd-55d1-b381-3c3134552e5d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 16, 16, 'A planet takes 4.5 Earth years to orbit its star. A second planet orbits the same star at 0.50 times the first planet''s orbit radius. Calculate the second planet''s period in Earth years.', NULL, 1, 'numeric'::answer_type, '1.591', 'years', false, NULL, false, NULL, 'T ∝ r^(3/2), so T₂ = 4.5 × 0.50^(3/2) = 4.5 × √(0.50³) = 1.59 years. Mark scheme (2 marks). C1: T² ∝ r³. A1: T = 1.59 years.', 2, NULL, NULL),
('00b33002-efa5-5502-923d-da3c4383282f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 17, 17, 'For circular orbits around the Earth, which graph gives a straight line through the origin?', NULL, 1, 'multiple_choice'::answer_type, 'T² against r³', NULL, false, NULL, false, NULL, 'T² = (4π²/GM)r³: plotting T² against r³ gives a straight line through the origin with gradient 4π²/GM. Mark scheme (1 mark). B1: B (T² against r³).', 1, NULL, NULL),
('f151437b-7d1c-5411-aa0e-af8723513db7', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 18, 18, 'Calculate the orbital period, in days, of a satellite orbiting the Earth at a radius of 1.0 × 10⁸ m. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '3.644', 'days', false, NULL, false, NULL, 'T = 2π√(r³/GM) = 2π × √((1.0 × 10⁸)³ ÷ 3.98 × 10¹⁴) = 3.15 × 10⁵ s. In days: 3.149 × 10⁵ ÷ 86400 = 3.64. Mark scheme (2 marks). C1: T = 2π√(r³/GM). A1: T = 3.64 days.', 2, NULL, NULL),
('a2a3c6f7-e204-553b-b73c-0facf30525f7', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 19, 19, 'Which quantity is the same for all satellites in circular orbits around the Earth?', NULL, 1, 'multiple_choice'::answer_type, 'T²/r³', NULL, false, NULL, false, NULL, 'T²/r³ = 4π²/GM, which depends only on the Earth''s mass. Mark scheme (1 mark). B1: C (T²/r³).', 1, NULL, NULL),
('5aa35350-250f-54ec-a800-e547015b2f75', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 20, 20, 'A satellite has period 2.0 h at a certain orbit radius. Another satellite of the same planet orbits at 2.0 times the radius. Calculate its period.', NULL, 1, 'numeric'::answer_type, '5.657', 'h', false, NULL, false, NULL, 'T ∝ r^(3/2): T = 2.0 × 2.0^(3/2) = 2.0 × √(2.0³) = 5.66 h. Mark scheme (2 marks). C1: T ∝ r^1.5. A1: T = 5.66 h.', 2, NULL, NULL),
('8824def8-baab-5794-af2c-98bc0bb6bf30', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 21, 21, 'A satellite moves into a higher circular orbit. Which change happens?', NULL, 1, 'multiple_choice'::answer_type, 'Its period increases and its speed decreases', NULL, false, NULL, false, NULL, 'T ∝ r^(3/2) and v ∝ r^(−1/2): higher orbits are slower and take longer. Mark scheme (1 mark). B1: A (Its period increases and its speed decreases).', 1, NULL, NULL),
('757b0878-8017-52e2-942d-6a054ee504fb', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 22, 22, 'Saturn''s moon Titan orbits at 1.22 × 10⁹ m with a period of 15.9 days. Calculate its orbital speed.', NULL, 1, 'numeric'::answer_type, '5580', 'm s⁻¹', false, NULL, false, NULL, 'v = 2πr/T = 2π × 1.22 × 10⁹ ÷ (15.9 × 86400) = 5580 m s⁻¹. Mark scheme (2 marks). C1: v = 2πr/T with T in s. A1: v = 5580 m s⁻¹.', 2, NULL, NULL),
('37764177-f9e6-53de-88d9-e58e57fd2102', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 23, 23, 'Planets further from the Sun take longer to orbit it. Which reason is correct?', NULL, 1, 'multiple_choice'::answer_type, 'They move more slowly and have further to travel', NULL, false, NULL, false, NULL, 'Further out, v = √(GM/r) is smaller and the circumference 2πr is larger, so T = 2πr/v grows as r^(3/2). Mark scheme (1 mark). B1: D (They move more slowly and have further to travel).', 1, NULL, NULL),
('9165aba5-b359-581f-9696-98d00dce628b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 24, 24, 'A satellite takes 100 minutes to orbit the Earth at 7.3 km s⁻¹. Calculate the radius of its orbit.', NULL, 1, 'numeric'::answer_type, '6.971e6', 'm', false, NULL, false, NULL, 'r = vT/2π = 7300 × 6000 ÷ 2π = 6.97 × 10⁶ m. Mark scheme (2 marks). C1: v = 2πr/T. A1: r = 6.97 × 10⁶ m.', 2, NULL, NULL),
('41eb19b5-3864-56fe-adef-ff6de4a7bbab', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 25, 25, 'Mars orbits the Sun at 1.52 times the Earth''s orbit radius. Use Kepler''s third law to calculate its orbital period in Earth years.', NULL, 1, 'numeric'::answer_type, '1.874', 'years', false, NULL, false, NULL, 'T ∝ r^(3/2): T = 1.52^(3/2) = √(1.52³) = 1.87 years. Mark scheme (2 marks). C1: T² ∝ r³ with Earth as reference. A1: T = 1.87 years.', 2, NULL, NULL),
('02396dd8-db7e-533f-af6a-1d1db32645c9', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 26, 26, 'The gravitational force on a satellite provides its centripetal force. Which equation follows directly?', NULL, 1, 'multiple_choice'::answer_type, 'GM/r² = 4π²r/T²', NULL, false, NULL, false, NULL, 'GMm/r² = mω²r = m(2π/T)²r, so GM/r² = 4π²r/T². Mark scheme (1 mark). B1: B (GM/r² = 4π²r/T²).', 1, NULL, NULL),
('6ee22d15-02be-5382-a404-1aa0efc62aab', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 27, 27, 'A navigation satellite has an orbital period of 12.0 hours. Calculate its orbital radius. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '2.66e7', 'm', false, NULL, false, NULL, 'T = 43200 s. r = (GMT²/4π²)^(1/3) = (3.98 × 10¹⁴ × 43200² ÷ (4π²))^(1/3) = 2.66 × 10⁷ m. Mark scheme (3 marks). C1: T in seconds. C1: r³ = GMT²/4π². C1: cube root.', 3, NULL, NULL),
('ad4f9b1b-d4cf-5baf-989b-5d0d61d915df', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 28, 28, 'Io orbits Jupiter at 4.22 × 10⁸ m with a period of 1.77 days. Calculate the mass of Jupiter. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '1.902e27', 'kg', false, NULL, false, NULL, 'T = 1.77 × 86400 = 1.53 × 10⁵ s. M = 4π²r³/GT² = 4π² × (4.22 × 10⁸)³ ÷ (6.67 × 10⁻¹¹ × (1.53 × 10⁵)²) = 1.90 × 10²⁷ kg. Mark scheme (3 marks). C1: T in seconds. C1: M = 4π²r³/GT². C1: substitution.', 3, NULL, NULL),
('48920c22-11b7-5394-8acd-449b26e8c10e', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 29, 29, 'The Earth orbits the Sun once a year (3.16 × 10⁷ s) at 1.50 × 10¹¹ m. Use this to determine the mass of the Sun. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '2e30', 'kg', false, NULL, false, NULL, 'M = 4π²r³/GT² = 4π² × (1.50 × 10¹¹)³ ÷ (6.67 × 10⁻¹¹ × (3.16 × 10⁷)²) = 2.00 × 10³⁰ kg. Mark scheme (4 marks). C1: gravity provides centripetal force. C1: M = 4π²r³/GT². C1: substitution. A1: M = 2.00 × 10³⁰ kg.', 4, NULL, NULL),
('f8ad8c9c-226d-590d-9547-28a47974ee85', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 30, 30, 'Two moons orbit the same planet. Moon P has period 2.0 days and moon Q has period 16 days. What is the ratio (orbit radius of Q)/(orbit radius of P)?', NULL, 2, 'multiple_choice'::answer_type, '4', NULL, false, NULL, false, NULL, 'r ∝ T^(2/3): (16/2)^(2/3) = 8^(2/3) = 4. Mark scheme (3 marks). C1: r³ ∝ T². C1: 8^(2/3) = 4. A1: C (4).', 3, NULL, NULL),
('1edad193-6368-579d-befe-f1f15ecf8921', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 31, 31, 'A planet of mass 4.0 × 10²⁴ kg has a moon with orbital period 25 days. Calculate the radius of the moon''s orbit. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '3.159e8', 'm', false, NULL, false, NULL, 'r = (GMT²/4π²)^(1/3) = (6.67 × 10⁻¹¹ × 4.0 × 10²⁴ × (25 × 86400)² ÷ (4π²))^(1/3) = 3.16 × 10⁸ m. Mark scheme (3 marks). C1: T in s. C1: r³ = GMT²/4π². C1: cube root.', 3, NULL, NULL),
('55605770-5ff0-505a-9e44-8d1bff863ea2', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 32, 32, 'Show which expression gives the orbital period of a satellite skimming the surface of a planet of radius R and uniform density ρ.', NULL, 2, 'multiple_choice'::answer_type, 'T = √(3π/Gρ)', NULL, false, NULL, false, NULL, 'T² = 4π²R³/GM with M = ⁴⁄₃πR³ρ gives T² = 3π/(Gρ): the period depends only on density. Mark scheme (3 marks). C1: M = ⁴⁄₃πR³ρ. C1: substitution into T² = 4π²R³/GM. A1: A (T = √(3π/Gρ)).', 3, NULL, NULL),
('03297695-8716-5bc6-8995-22c86a8f07e2', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 33, 33, 'A planet of mean density 5500 kg m⁻³ is orbited by a satellite just above its surface. Calculate the period, using T = √(3π/Gρ). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '5069', 's', false, NULL, false, NULL, 'T = √(3π ÷ (6.67 × 10⁻¹¹ × 5500)) = 5070 s. Mark scheme (3 marks). C1: formula. C1: substitution. A1: T = 5070 s.', 3, NULL, NULL),
('f92cdf3f-5d03-54dc-b7e8-d476706e92e9', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 34, 34, 'A space station orbits at 420 km above the Earth''s surface. Calculate how many complete orbits it makes in one day. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '15.51', NULL, false, 0.02, false, NULL, 'r = 6.79 × 10⁶ m. T = 2π√(r³/GM) = 2π × √((6.79 × 10⁶)³ ÷ 3.98 × 10¹⁴) = 5570 s. Orbits per day = 86400 ÷ 5571 = 15.5. Mark scheme (4 marks). C1: r = R + h. C1: T = 2π√(r³/GM). C1: 86 400/T. A1: orbits = 15.5.', 4, NULL, NULL),
('b5c53182-f732-5fa3-ae1f-3ecf6b00aaa2', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 35, 35, 'Two planets orbit the same star. Planet A has twice the orbit radius of planet B. Which is correct about their speeds and periods?', NULL, 2, 'multiple_choice'::answer_type, 'A is slower by √2 and takes 2√2 times as long', NULL, false, NULL, false, NULL, 'v ∝ r^(−½): v_A = v_B/√2. T ∝ r^(3/2): T_A = 2^(3/2) T_B = 2√2 T_B. Mark scheme (3 marks). C1: v ∝ r^(−1/2). C1: T ∝ r^(3/2). A1: D (A is slower by √2 and takes 2√2 times as long).', 3, NULL, NULL),
('086dc3ce-8e14-51c9-ab32-6c95508a3602', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 36, 36, 'The ratio T²/r³ for satellites of a particular planet is 9.9 × 10⁻¹⁴ s² m⁻³. Calculate the mass of the planet. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '5.979e24', 'kg', false, NULL, false, NULL, 'T²/r³ = 4π²/GM, so M = 4π² ÷ (G × T²/r³) = 4π² ÷ (6.67 × 10⁻¹¹ × 9.9 × 10⁻¹⁴) = 5.98 × 10²⁴ kg. Mark scheme (3 marks). C1: T²/r³ = 4π²/GM. C1: rearranged for M. A1: M = 5.98 × 10²⁴ kg.', 3, NULL, NULL),
('70432a6c-ae33-59a6-99a5-b5c6906d9f5f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 37, 37, 'A satellite orbits a moon of mass 7.35 × 10²² kg once every 2.0 hours. Calculate its orbital radius, and its height above the moon''s surface (radius 1.74 × 10⁶ m). Give the height. Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 2, 'numeric'::answer_type, '1.203e5', 'm', false, NULL, false, NULL, 'r = (GMT²/4π²)^(1/3) = (6.67 × 10⁻¹¹ × 7.35 × 10²² × 7200² ÷ (4π²))^(1/3) = 1.86 × 10⁶ m. Height = 1.860 × 10⁶ − 1.74 × 10⁶ = 1.20 × 10⁵ m. Mark scheme (4 marks). C1: T in s. C1: cube-root formula. C1: subtract radius. A1: h = 1.20 × 10⁵ m.', 4, NULL, NULL),
('4be53af3-469d-54b1-a565-14158075217f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 38, 38, 'A student derives T² = 4π²r³/GM. Which is the key physical assumption?', NULL, 2, 'multiple_choice'::answer_type, 'The gravitational force on the satellite provides exactly the centripetal force for a circular orbit', NULL, false, NULL, false, NULL, 'Setting GMm/r² = mω²r assumes a circular orbit with gravity as the only (centripetal) force, and that M ≫ m so the planet stays still. Mark scheme (3 marks). C1: gravity = centripetal force. C1: circular orbit. A1: B (The gravitational force on the satellite provides exactly the centripetal force for a circular orbit).', 3, NULL, NULL),
('61d6f9c6-9e64-52fd-80cb-08400f06a55c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 39, 39, 'Neptune orbits the Sun at 30.1 times the Earth''s orbit radius. Calculate its orbital period in Earth years.', NULL, 2, 'numeric'::answer_type, '165.1', 'years', false, NULL, false, NULL, 'T = 30.1^(3/2) = √(30.1³) = 165 years. Mark scheme (3 marks). C1: T² ∝ r³. C1: Earth as reference (1 year, 1 unit). A1: T = 165 years.', 3, NULL, NULL),
('d1bbe8b2-d0e3-5f18-b907-27bc1ef0977f', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 40, 40, 'A moon has orbital radius 1.9 × 10⁸ m and period 3.5 days. A second moon of the same planet has period 14 days. Calculate the orbital radius of the second moon without using G.', NULL, 2, 'numeric'::answer_type, '4.788e8', 'm', false, NULL, false, NULL, 'r ∝ T^(2/3): r₂ = 1.9 × 10⁸ × (14 ÷ 3.5)^(2/3) = 1.9 × 10⁸ × 4^(2/3) = 4.79 × 10⁸ m. Mark scheme (4 marks). C1: T² ∝ r³. C1: ratio of periods = 4. C1: 4^(2/3). A1: r = 4.79 × 10⁸ m.', 4, NULL, NULL),
('e211fef3-4d34-5561-8802-e610e1628291', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 41, 41, 'Astronomers measure the period T and radius r of the orbits of several moons of a planet and plot lg T against lg r. What is the gradient of the line?', NULL, 2, 'multiple_choice'::answer_type, '1.5', NULL, false, NULL, false, NULL, 'T = kr^(3/2), so lg T = 1.5 lg r + lg k: a straight line of gradient 1.5. Mark scheme (4 marks). C1: T ∝ r^(3/2). C1: logs give gradient = power. C1: 1.5. A1: C (1.5).', 4, NULL, NULL),
('28793863-3945-5630-b797-a404910be992', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 42, 42, 'A satellite in a 98-minute orbit is moved to an orbit with 4.0 times the period. By what factor does its orbital radius increase?', NULL, 2, 'numeric'::answer_type, '2.52', NULL, false, NULL, false, NULL, 'r ∝ T^(2/3): factor = 4.0^(2/3) = 2.52. Mark scheme (3 marks). C1: T² ∝ r³. C1: power 2/3. A1: factor = 2.52.', 3, NULL, NULL),
('14a041f0-f9f5-56ca-90a6-c6de0636a121', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 43, 43, 'Kepler found that for the planets, T²/r³ has the same value. A newly discovered dwarf planet has an orbit radius 40 times the Earth''s. Which period is closest?', NULL, 2, 'multiple_choice'::answer_type, '250 years', NULL, false, NULL, false, NULL, 'T = 40^(3/2) years = √(64 000) ≈ 253 years. Mark scheme (3 marks). C1: T² ∝ r³ relative to the Earth. C1: 40^1.5. A1: A (250 years).', 3, NULL, NULL),
('c11d108f-3bfb-5645-a303-6ff036afa2fa', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 44, 44, 'Data for moons of a planet: moon A r = 1.0 × 10⁸ m, T = 1.0 × 10⁵ s; moon B r = 4.0 × 10⁸ m, T = 8.0 × 10⁵ s; moon C r = 9.0 × 10⁸ m, T = 2.7 × 10⁶ s. (a) Show that the data obey Kepler''s third law. (b) Calculate T²/r³. (c) Calculate the mass of the planet. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '5.919e25', 'kg', false, NULL, false, NULL, '(a) T²/r³: A = (1.0 × 10⁵)² ÷ (1.0 × 10⁸)³ = 1.0 × 10⁻¹⁴, B = (8.0 × 10⁵)² ÷ (4.0 × 10⁸)³ = 1.0 × 10⁻¹⁴, C = (2.7 × 10⁶)² ÷ (9.0 × 10⁸)³ = 1.0 × 10⁻¹⁴ s² m⁻³: constant. (b) 1.0 × 10⁻¹⁴ s² m⁻³. (c) M = 4π² ÷ (G × T²/r³) = 4π² ÷ (6.67 × 10⁻¹¹ × 1.0 × 10⁻¹⁴) = 5.92 × 10²⁵ kg. Mark scheme (6 marks). M1: T²/r³ for at least two moons. A1: constant. A1: value. C1: T²/r³ = 4π²/GM. C1: rearranged. A1: M = 5.92 × 10²⁵ kg.', 6, NULL, NULL),
('48b60e4f-f267-50cc-a6c4-d6e1669eb49b', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 45, 45, 'A satellite is to be placed in a circular orbit with period 6.0 hours. (a) Calculate its orbital radius. (b) Calculate its height above the surface. (c) Calculate its orbital speed. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '1.039e7', 'm', false, NULL, false, NULL, '(a) T = 21600 s, r = (GMT²/4π²)^(1/3) = (3.98 × 10¹⁴ × 21600² ÷ (4π²))^(1/3) = 1.68 × 10⁷ m. (b) h = 1.676 × 10⁷ − 6.37 × 10⁶ = 1.04 × 10⁷ m. (c) v = 2πr/T = 4870 m s⁻¹. Mark scheme (5 marks). C1: T in s. C1: r³ = GMT²/4π². A1: r. A1: h = 1.04 × 10⁷ m. B1: v = 2πr/T.', 5, NULL, NULL),
('ebbaa168-f688-5b03-8c87-b0b87a0b657d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 46, 46, '(a) Starting from Newton''s law of gravitation, derive T² = (4π²/GM)r³ for a circular orbit. (b) A distant star has a planet with orbital radius 7.5 × 10⁹ m and period 4.2 days. Calculate the mass of the star. (c) Express it as a multiple of the Sun''s mass (1.99 × 10³⁰ kg). Give only the multiple in (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '0.9529', NULL, false, NULL, false, NULL, '(a) GMm/r² = mω²r and ω = 2π/T, so GM/r² = 4π²r/T² and T² = (4π²/GM)r³. (b) M = 4π²r³/GT² = 4π² × (7.5 × 10⁹)³ ÷ (6.67 × 10⁻¹¹ × (4.2 × 86400)²) = 1.90 × 10³⁰ kg. (c) multiple = 1.896 × 10³⁰ ÷ 1.99 × 10³⁰ = 0.953. Mark scheme (6 marks). M1: GMm/r² = mω²r. M1: ω = 2π/T. A1: T² = 4π²r³/GM. C1: T in s. A1: M. A1: multiple = 0.953.', 6, NULL, NULL),
('a8e77f9d-b4ff-51fc-b97d-a94cbfbb8a69', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 47, 47, 'A planet orbits a star with period 225 days at radius 1.08 × 10¹¹ m. A comet passes the same star in a nearly circular path at 2.7 × 10¹¹ m. (a) Calculate GM for the star from the planet''s data. (b) Calculate the comet''s period in days, if its path were circular. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '889.4', 'days', false, NULL, false, NULL, '(a) GM = 4π²r³/T² = 4π² × (1.08 × 10¹¹)³ ÷ (225 × 86400)² = 1.32 × 10²⁰ N m² kg⁻¹. (b) T ∝ r^(3/2): T = 225 × (2.7 ÷ 1.08)^1.5 = 889 days. Mark scheme (5 marks). C1: GM = 4π²r³/T². A1: GM. C1: Kepler ratio. C1: power 3/2. A1: T = 889 days.', 5, NULL, NULL),
('9ea1bfb6-a7fd-5780-906b-31c4857b90da', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 48, 48, 'Two planets orbit a star. Planet X has period 1.0 year and radius 1.0 AU. Planet Y has period 8.0 years. (a) Calculate the orbit radius of Y in AU. (b) Calculate the ratio of their orbital speeds v_X/v_Y. (c) Explain why the planets'' masses are not needed. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, '(a) r ∝ T^(2/3): r_Y = 8.0^(2/3) = 4.0 AU. (b) v = 2πr/T: v_X/v_Y = (1.0 ÷ 1.0) ÷ (4.0 ÷ 8.0) = 2.0. (c) T² = 4π²r³/GM depends only on the star''s mass M; the planet''s mass cancels. Mark scheme (6 marks). C1: r ∝ T^(2/3). A1: 4.0 AU. C1: v = 2πr/T. A1: ratio = 2.0. B1: planet mass cancels. B1: only star mass M.', 6, NULL, NULL),
('3dd71823-f92a-59d0-9386-9963dcb7a835', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 49, 49, 'A student plots T² (in s²) against r³ (in m³) for four satellites of a planet and obtains a straight line through the origin with gradient 2.3 × 10⁻¹³ s² m⁻³. (a) Explain why the line passes through the origin. (b) Calculate the mass of the planet. (c) Calculate the period of a satellite at r = 5.0 × 10⁷ m. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '1.696e5', 's', false, NULL, false, NULL, '(a) T² = (4π²/GM)r³ has no constant term. (b) M = 4π² ÷ (G × gradient) = 4π² ÷ (6.67 × 10⁻¹¹ × 2.3 × 10⁻¹³) = 2.57 × 10²⁴ kg. (c) T = √(2.3 × 10⁻¹³ × (5.0 × 10⁷)³) = 1.70 × 10⁵ s. Mark scheme (5 marks). B1: T² ∝ r³ with no intercept. C1: gradient = 4π²/GM. A1: M. C1: T² = gradient × r³. A1: T = 1.70 × 10⁵ s.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgc2be54c1-t fgc2be54c1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc2be54c1-t">T² against r³</title><desc id="fgc2be54c1-d">Graph of T² against r³ for four satellites: a straight line through the origin with gradient 2.3 × 10⁻¹³ s² m⁻³.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="112.4" y1="34" x2="112.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="195.4" y1="34" x2="195.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278.3" y1="34" x2="278.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="361.3" y1="34" x2="361.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="242" x2="29.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="112.4" y1="242" x2="112.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="112.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="195.4" y1="242" x2="195.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="195.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="278.3" y1="242" x2="278.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="278.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6</text><line x1="361.3" y1="242" x2="361.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="361.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="190" x2="29.4" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">5</text><line x1="25.4" y1="138" x2="29.4" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><line x1="25.4" y1="86" x2="29.4" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">15</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r³ / 10²² m³</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">T² / 10⁹ s²</text><polyline points="29.4,242 361.3,50.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="41.9" y="65.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">gradient 2.3 × 10⁻¹³ s² m⁻³</text></svg>', 'Graph of T² against r³ for four satellites: a straight line through the origin with gradient 2.3 × 10⁻¹³ s² m⁻³.'),
('d9da30bf-50b6-57f6-a5c5-369f21e9c53a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', 'bfae2a74-7c35-44c1-b9b0-f286554f329b', 'a-level', '17.6', '9702 coursebook 17.6 · The orbital period', 50, 50, 'A binary star system: two equal stars, each of mass M, orbit their common centre at the ends of a diameter of a circle of radius r (so they are 2r apart). (a) Show that the force on each star is GM²/4r². (b) Show that T² = 16π²r³/GM. (c) For r = 1.5 × 10¹¹ m and T = 3.2 × 10⁷ s, calculate M. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '7.803e30', 'kg', false, NULL, false, NULL, '(a) Separation 2r: F = GM·M/(2r)² = GM²/4r². (b) GM²/4r² = Mω²r = M(4π²/T²)r, so T² = 16π²r³/GM. (c) M = 16π²r³/(GT²) = 16π² × (1.5 × 10¹¹)³ ÷ (6.67 × 10⁻¹¹ × (3.2 × 10⁷)²) = 7.80 × 10³⁰ kg. Mark scheme (6 marks). M1: separation 2r. A1: GM²/4r². M1: equated to Mω²r. A1: T² expression. C1: rearranged. A1: M = 7.80 × 10³⁰ kg.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 138" role="img" aria-labelledby="fgbae391d3-t fgbae391d3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbae391d3-t">Binary stars</title><desc id="fgbae391d3-d">Two equal stars, each of mass M, at opposite ends of a diameter of a circle of radius r about their common centre C, so they are 2r apart.</desc><polygon points="70,90 76.3,87 76.3,93" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="90" x2="205.1" y2="90" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="210,90 203.7,93 203.7,87" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="140" y="102" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r</text><polygon points="210,90 216.3,87 216.3,93" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="214.9" y1="90" x2="345.1" y2="90" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="350,90 343.7,93 343.7,87" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="280" y="102" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r</text><circle cx="70" cy="48" r="12" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">M</text><circle cx="350" cy="48" r="12" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="350" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">M</text><circle cx="210" cy="48" r="3.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="218" y="36" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">C</text></svg>', 'Two equal stars, each of mass M, at opposite ends of a diameter of a circle of radius r about their common centre C, so they are 2r apart.')
