('3fc180a2-2ce3-5213-87c0-d2f965e2d11b', 'e211fef3-4d34-5561-8802-e610e1628291', '2', 'D', false, 3),
('669b5f22-587a-5032-b843-f6e0c73804dc', '14a041f0-f9f5-56ca-90a6-c6de0636a121', '250 years', 'A', true, 0),
('56f797b6-3d60-5f67-ba03-19ee0039da8d', '14a041f0-f9f5-56ca-90a6-c6de0636a121', '40 years', 'B', false, 1),
('c4bc996d-41c8-5b4d-b35f-4b5fdcc8a39d', '14a041f0-f9f5-56ca-90a6-c6de0636a121', '1600 years', 'C', false, 2),
('9a34ee4a-dd95-539f-8969-d51ed3e6db16', '14a041f0-f9f5-56ca-90a6-c6de0636a121', '6.3 years', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('992791db-00eb-5386-82f0-6bb097ea58b5', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 12, 12, 'Which is NOT a requirement for a geostationary orbit?', NULL, 1, 'multiple_choice'::answer_type, 'The satellite must have a mass of exactly 1000 kg', NULL, false, NULL, false, NULL, 'Geostationary: equatorial, period one sidereal day, moving west to east. The orbit does not depend on the satellite''s mass. Mark scheme (1 mark). B1: C (The satellite must have a mass of exactly 1000 kg).', 1, NULL, NULL),
('c0948d15-ecde-5180-b8da-03bdefc454dc', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 13, 13, 'Why are geostationary satellites useful for satellite television?', NULL, 1, 'multiple_choice'::answer_type, 'They stay above the same point on the Earth, so dishes need not track them', NULL, false, NULL, false, NULL, 'A geostationary satellite has the same angular speed as the Earth, so it appears fixed in the sky and a fixed dish can point at it. Mark scheme (1 mark). B1: A (They stay above the same point on the Earth, so dishes need not track them).', 1, NULL, NULL),
('1714bfce-a88a-5975-9e9d-b8a1cc2cccf7', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 14, 14, 'A polar-orbiting satellite passes over both poles. Why is this orbit useful for Earth observation?', NULL, 1, 'multiple_choice'::answer_type, 'The Earth rotates beneath it, so over successive orbits it can view every part of the surface', NULL, false, NULL, false, NULL, 'Each orbit passes over a different strip of the Earth as the planet rotates underneath, so the whole surface is mapped in a day or so. Mark scheme (1 mark). B1: D (The Earth rotates beneath it, so over successive orbits it can view every part of the surface).', 1, NULL, NULL),
('f52e3ddf-d8f3-5fb0-a8d6-3e263fcb85a0', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 15, 15, 'Astronauts on the International Space Station float freely. What is the correct explanation?', NULL, 1, 'multiple_choice'::answer_type, 'They and the station are in free fall around the Earth, with the same acceleration', NULL, false, NULL, false, NULL, 'Gravity at 400 km is about 90 % of its surface value. Everything in the station accelerates towards the Earth at the same rate, so there is no contact force and the astronauts feel weightless. Mark scheme (1 mark). B1: B (They and the station are in free fall around the Earth, with the same acceleration).', 1, NULL, NULL),
('c3507fcb-378a-5a6d-be7b-d6bf5348a867', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 16, 16, 'Low Earth orbit satellites have periods of about 90 minutes. What is the approximate period of a geostationary satellite?', NULL, 1, 'multiple_choice'::answer_type, '24 hours', NULL, false, NULL, false, NULL, 'A geostationary satellite must keep pace with the Earth''s rotation: one orbit per (sidereal) day, about 24 h. Mark scheme (1 mark). B1: C (24 hours).', 1, NULL, NULL),
('7b31b6fd-d1df-57a3-9e1f-03604a3cf9bf', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 17, 17, 'A geostationary satellite orbits at 4.22 × 10⁷ m from the Earth''s centre. Calculate its height above the surface. Earth''s radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '3.583e7', 'm', false, NULL, false, NULL, 'h = r − R = 4.22 × 10⁷ − 6.37 × 10⁶ = 3.58 × 10⁷ m. Mark scheme (2 marks). C1: h = r − R. A1: h = 3.58 × 10⁷ m.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fge61cac67-t fge61cac67-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge61cac67-t">Geostationary orbit</title><desc id="fge61cac67-d">The Earth (radius 6.37 × 10⁶ m) and a geostationary orbit of radius 4.22 × 10⁷ m from the Earth''s centre, drawn to scale.</desc><circle cx="180" cy="160" r="19" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="180" cy="160" r="126" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="174" y="30" width="12" height="8" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="160" x2="180" y2="34" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><text x="188" y="102" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">4.22 × 10⁷ m</text></svg>', 'The Earth (radius 6.37 × 10⁶ m) and a geostationary orbit of radius 4.22 × 10⁷ m from the Earth''s centre, drawn to scale.'),
('89b53243-6b15-5342-96de-d78662964dd6', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 18, 18, 'Calculate the speed of a geostationary satellite, orbit radius 4.22 × 10⁷ m, period 86 164 s.', NULL, 1, 'numeric'::answer_type, '3077', 'm s⁻¹', false, NULL, false, NULL, 'v = 2πr/T = 2π × 4.22 × 10⁷ ÷ 86164 = 3080 m s⁻¹. Mark scheme (2 marks). C1: v = 2πr/T. A1: v = 3080 m s⁻¹.', 2, NULL, NULL),
('c3d61227-4f8f-575c-8c24-679948bf0d76', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 19, 19, 'A satellite in low Earth orbit is 500 km above the surface. Calculate its distance from the Earth''s centre. Earth''s radius = 6.37 × 10⁶ m.', NULL, 1, 'numeric'::answer_type, '6.87e6', 'm', false, NULL, false, NULL, 'r = R + h = 6.37 × 10⁶ + 5.0 × 10⁵ = 6.87 × 10⁶ m. Mark scheme (2 marks). C1: r = R + h. A1: r = 6.87 × 10⁶ m.', 2, NULL, NULL),
('aedac8c0-7a1e-542f-a843-042b6ce87ce1', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 20, 20, 'A ground station sees a geostationary satellite. In which direction does the satellite appear to move across the sky?', NULL, 1, 'multiple_choice'::answer_type, 'It does not move: it stays in the same position', NULL, false, NULL, false, NULL, 'It turns with the Earth, so relative to an observer on the ground it is stationary. Mark scheme (1 mark). B1: A (It does not move: it stays in the same position).', 1, NULL, NULL),
('7a1895bb-69bd-5c83-b972-c22ccd00a34d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 21, 21, 'Signals to a geostationary satellite and back take a noticeable time. Approximately how long does a signal take to go up and down again (straight above the transmitter)?', NULL, 1, 'multiple_choice'::answer_type, '0.24 s', NULL, false, NULL, false, NULL, 'The height is about 3.6 × 10⁷ m. Distance up and down ≈ 7.2 × 10⁷ m, time = 7.2 × 10⁷ ÷ 3.0 × 10⁸ ≈ 0.24 s. Mark scheme (1 mark). B1: D (0.24 s).', 1, NULL, NULL),
('f6330c17-221a-5268-9897-2698c51e60f0', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 22, 22, 'Calculate the time for a radio signal to travel from the ground to a geostationary satellite directly overhead, 3.58 × 10⁷ m above the surface. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '0.1193', 's', false, NULL, false, NULL, 't = d/c = 3.58 × 10⁷ ÷ 3.00 × 10⁸ = 0.119 s. Mark scheme (2 marks). C1: t = d/c. A1: t = 0.119 s.', 2, NULL, NULL),
('77134dec-b25d-5c71-81d3-c279178d2daf', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 23, 23, 'What is the direction of motion of a geostationary satellite?', NULL, 1, 'multiple_choice'::answer_type, 'West to east, the same way the Earth rotates', NULL, false, NULL, false, NULL, 'To stay above the same point it must move round in the same sense as the Earth spins: west to east. Mark scheme (1 mark). B1: B (West to east, the same way the Earth rotates).', 1, NULL, NULL),
('70e111fd-95a5-5c89-9e66-a8a179aac042', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 24, 24, 'Which of these satellites would most likely be in a low polar orbit?', NULL, 1, 'multiple_choice'::answer_type, 'A weather-mapping and imaging satellite', NULL, false, NULL, false, NULL, 'Low polar orbits give high-resolution views of the whole globe as the Earth turns underneath. Mark scheme (1 mark). B1: C (A weather-mapping and imaging satellite).', 1, NULL, NULL),
('382598ca-ec6c-5300-a01a-9e46e6db7c67', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 25, 25, 'A polar satellite takes 100 minutes per orbit. How many orbits does it complete in one day?', NULL, 1, 'numeric'::answer_type, '14.4', NULL, false, NULL, false, NULL, 'orbits per day = 1440 ÷ 100 = 14.4. Mark scheme (2 marks). C1: minutes in a day ÷ period. A1: orbits = 14.4.', 2, NULL, NULL),
('43336ae4-2f56-599f-94ca-183c1fa18496', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 26, 26, 'A satellite in a circular orbit is at a height of 300 km. What is the main reason it eventually falls to Earth unless boosted?', NULL, 1, 'multiple_choice'::answer_type, 'Drag from the very thin upper atmosphere removes energy', NULL, false, NULL, false, NULL, 'Even at 300 km there is a tiny amount of air. Drag removes energy, the orbit shrinks, and eventually the satellite re-enters. Mark scheme (1 mark). B1: A (Drag from the very thin upper atmosphere removes energy).', 1, NULL, NULL),
('feee1b01-b7d0-5e1c-b576-8b7c0cf56797', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 27, 27, 'An astronaut has mass 75 kg. On the ISS, where g = 8.7 N kg⁻¹, calculate the gravitational force on the astronaut.', NULL, 1, 'numeric'::answer_type, '652.5', 'N', false, NULL, false, NULL, 'F = mg = 75 × 8.7 = 652 N — not zero, even though the astronaut feels weightless. Mark scheme (2 marks). C1: F = mg with g at the orbit. A1: F = 652 N.', 2, NULL, NULL),
('1f303b8b-78ff-553a-9d84-c056f12dc80a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 28, 28, 'The ISS orbits 6.79 × 10⁶ m from the Earth''s centre at 7.66 km s⁻¹. Calculate the time for one orbit in minutes.', NULL, 1, 'numeric'::answer_type, '92.83', 'minutes', false, NULL, false, NULL, 'T = 2πr/v = 2π × 6.79 × 10⁶ ÷ 7660 = 5570 s. In minutes: 5570 ÷ 60 = 92.8. Mark scheme (2 marks). C1: T = 2πr/v. A1: T = 92.8 minutes.', 2, NULL, NULL),
('52872741-2d31-53d0-8684-cf7a26acb7e2', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 29, 29, 'Show that the radius of a geostationary orbit is about 4.2 × 10⁷ m, using a sidereal day of 86 164 s. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m. Give your value.', NULL, 2, 'numeric'::answer_type, '4.215e7', 'm', false, NULL, false, NULL, 'r = (GMT²/4π²)^(1/3) = (3.98 × 10¹⁴ × 86164² ÷ (4π²))^(1/3) = 4.21 × 10⁷ m. Mark scheme (3 marks). C1: GMm/r² = mω²r. C1: r³ = GMT²/4π². C1: substitution and cube root.', 3, NULL, NULL),
('e5e76d81-e2d5-548b-8cfc-1b527b35de2c', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 30, 30, 'Calculate the gravitational field strength at a geostationary orbit, radius 4.22 × 10⁷ m, and compare it with g at the surface. Give the field strength. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '0.2236', 'N kg⁻¹', false, NULL, false, NULL, 'g = GM/r² = 3.98 × 10¹⁴ ÷ (4.22 × 10⁷)² = 0.224 N kg⁻¹, about 1/44 of the surface value. Mark scheme (3 marks). C1: g = GM/r². C1: substitution. B1: comparison.', 3, NULL, NULL),
('fdbdf562-ab35-50f9-8dfb-da60f8bbf6bd', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 31, 31, 'A geostationary satellite drifts slightly lower than the correct orbit radius. What happens to it, as seen from the ground?', NULL, 2, 'multiple_choice'::answer_type, 'It slowly drifts eastwards, because its period is now slightly less than a day', NULL, false, NULL, false, NULL, 'A lower orbit has a shorter period (T ∝ r^(3/2)), so the satellite gets ahead of the rotating Earth and appears to move east. Mark scheme (3 marks). C1: lower orbit, shorter period. C1: moves ahead of the Earth (east). A1: D (It slowly drifts eastwards, because its period is now slightly less than a day).', 3, NULL, NULL),
('cf3aa8b6-a338-5c0e-b6f0-9b2a9fdd14de', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 32, 32, 'A satellite in a low circular orbit 350 km above the Earth passes overhead. Calculate its orbital speed and period. Give the period in minutes. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '91.42', 'minutes', false, NULL, false, NULL, 'r = 6.72 × 10⁶ m. v = √(GM/r) = √(3.98 × 10¹⁴ ÷ 6.72 × 10⁶) = 7700 m s⁻¹. T = 2πr/v = 2π × 6.72 × 10⁶ ÷ 7698 = 5490 s. In minutes: 5485 ÷ 60 = 91.4. Mark scheme (4 marks). C1: r = R + h. C1: v = √(GM/r). C1: T = 2πr/v. A1: T = 91.4 minutes.', 4, NULL, NULL),
('a16e2b0c-42af-580a-9feb-f85d561bd895', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 33, 33, 'Why must a geostationary satellite be above the Equator?', NULL, 2, 'multiple_choice'::answer_type, 'The centre of its circular orbit must be the Earth''s centre, and only an equatorial orbit keeps it over one point as the Earth spins', NULL, false, NULL, false, NULL, 'Any orbit is centred on the Earth''s centre. An inclined orbit would carry the satellite north and south of the Equator each day, so it could not stay above one point. Mark scheme (3 marks). C1: orbit centred on Earth''s centre. C1: inclined orbit oscillates north–south. A1: B (The centre of its circular orbit must be the Earth''s centre, and only an equatorial orbit keeps it over one point as the Earth spins).', 3, NULL, NULL),
('05bdcf05-8f5d-5ae4-84a2-21ca4c1afac3', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 34, 34, 'An Earth-observation satellite is designed to make exactly 15 orbits per sidereal day (86 164 s). Calculate its orbital radius and its height above the surface. Give the height. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '5.601e5', 'm', false, NULL, false, NULL, 'T = 86164 ÷ 15 = 5740 s. r = (GMT²/4π²)^(1/3) = (3.98 × 10¹⁴ × 5744² ÷ (4π²))^(1/3) = 6.93 × 10⁶ m. Height = 6.930 × 10⁶ − 6.37 × 10⁶ = 5.60 × 10⁵ m. Mark scheme (4 marks). C1: T = day/15. C1: r from Kepler/Newton. C1: h = r − R. A1: h = 5.60 × 10⁵ m.', 4, NULL, NULL),
('521c779c-1b1a-563c-9e60-7177da75f75d', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 35, 35, 'An astronaut on the ISS drops a pen. Which describes what happens?', NULL, 2, 'multiple_choice'::answer_type, 'The pen floats beside the astronaut because both are falling around the Earth at the same rate', NULL, false, NULL, false, NULL, 'The pen, astronaut and station all have the same acceleration (g at that height) towards the Earth, so relative to the station the pen stays put. Mark scheme (3 marks). C1: everything has the same acceleration. C1: no relative motion. A1: C (The pen floats beside the astronaut because both are falling around the Earth at the same rate).', 3, NULL, NULL),
('b2d31445-05b5-5343-accf-e8458ff31fcd', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 36, 36, 'A 120 kg satellite is in a geostationary orbit (r = 4.22 × 10⁷ m). Calculate the gravitational force on it. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '26.83', 'N', false, NULL, false, NULL, 'F = GMm/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 120 ÷ (4.22 × 10⁷)² = 26.8 N. Mark scheme (3 marks). C1: F = GMm/r². C1: r from centre. A1: F = 26.8 N.', 3, NULL, NULL),
('69d69554-c841-5f38-a6c1-8e759f307a92', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 37, 37, 'Why do most satellite launches from the ground head eastwards?', NULL, 2, 'multiple_choice'::answer_type, 'They gain the Earth''s rotational speed (up to about 465 m s⁻¹ at the Equator)', NULL, false, NULL, false, NULL, 'The launch site already moves east with the rotating Earth, so launching east reduces the extra speed the rocket must supply. Mark scheme (3 marks). C1: Earth''s surface moves east. C1: less extra speed needed. A1: A (They gain the Earth''s rotational speed (up to about 465 m s⁻¹ at the Equator)).', 3, NULL, NULL),
('1c054a67-de10-5fd5-abdd-b076b73fd112', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 38, 38, 'A geostationary satellite is directly above a ground station on the Equator. A phone call relayed by it travels ground → satellite → ground, then the reply comes back the same way. Calculate the delay between speaking and hearing the reply, due to the signal travel time. Height = 3.58 × 10⁷ m. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '0.4773', 's', false, NULL, false, NULL, 'Total path = 4 × 3.58 × 10⁷ = 1.43 × 10⁸ m. t = 1.43 × 10⁸ ÷ 3.00 × 10⁸ = 0.477 s. Mark scheme (4 marks). C1: four legs. C1: t = d/c. C1: substitution. A1: t = 0.477 s.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fgf9d09143-t fgf9d09143-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf9d09143-t">Relay by a geostationary satellite</title><desc id="fgf9d09143-d">A geostationary satellite directly above a ground station on the Equator; signals travel straight up and down between them.</desc><circle cx="180" cy="160" r="19" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="180" cy="160" r="126" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="174" y="30" width="12" height="8" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="141" x2="180" y2="34" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 3"/><circle cx="180" cy="141" r="3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="188" y="133" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">ground station</text></svg>', 'A geostationary satellite directly above a ground station on the Equator; signals travel straight up and down between them.'),
('fab07449-52ee-5437-a039-8637369e5324', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 39, 39, 'At what height above the Earth''s surface would a satellite have an orbital period of 2.0 hours? Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '1.686e6', 'm', false, NULL, false, NULL, 'r = (3.98 × 10¹⁴ × 7200² ÷ (4π²))^(1/3) = 8.06 × 10⁶ m. h = 8.056 × 10⁶ − 6.37 × 10⁶ = 1.69 × 10⁶ m. Mark scheme (3 marks). C1: T in s. C1: r³ = GMT²/4π². C1: h = r − R.', 3, NULL, NULL),
('e2b9925a-2a32-5af2-b685-3e43b65e6200', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 40, 40, 'Two satellites are in circular orbits: S₁ geostationary, S₂ in a low polar orbit. Which row is correct?', NULL, 2, 'multiple_choice'::answer_type, 'S₁ has the longer period and lower speed; S₂ has the stronger gravitational field acting on it per kg', NULL, false, NULL, false, NULL, 'Higher orbit: longer period (T ∝ r^1.5), lower speed (v ∝ r^−0.5), weaker g (∝ 1/r²). S₁ is much higher than S₂. Mark scheme (4 marks). C1: T ∝ r^1.5. C1: v ∝ r^−0.5. C1: g ∝ 1/r². A1: D (S₁ has the longer period and lower speed; S₂ has the stronger gravitational field acting on it per kg).', 4, NULL, NULL),
('2b4c5258-e406-5e04-a36c-51cc15b935ad', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 41, 41, 'An astronaut of mass 80 kg sits on bathroom scales in a spacecraft in orbit. What do the scales read?', NULL, 2, 'multiple_choice'::answer_type, 'Zero, because the astronaut and scales fall together and press on each other with no force', NULL, false, NULL, false, NULL, 'Scales measure the contact force. In orbit both the scales and the astronaut accelerate at g, so there is no contact force and the reading is zero, even though gravity still pulls on the astronaut. Mark scheme (3 marks). C1: scales measure contact force. C1: both in free fall. A1: B (Zero, because the astronaut and scales fall together and press on each other with no force).', 3, NULL, NULL),
('98e400ec-0c02-501c-a180-3544f4e5f843', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 42, 42, 'A satellite is in a circular orbit of radius 2.66 × 10⁷ m (a GPS orbit). Calculate its period in hours and the number of orbits it makes per day. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m. Give the period in hours.', NULL, 2, 'numeric'::answer_type, '12', 'h', false, NULL, false, NULL, 'T = 2π√(r³/GM) = 2π × √((2.66 × 10⁷)³ ÷ 3.98 × 10¹⁴) = 4.32 × 10⁴ s. In hours: 4.320 × 10⁴ ÷ 3600 = 12.0 — about two orbits per day. Mark scheme (4 marks). C1: T = 2π√(r³/GM). C1: convert to hours. C1: orbits per day. A1: T = 12.0 h.', 4, NULL, NULL),
('3314e0d7-4766-5602-aafa-e4f4dab810fb', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 43, 43, 'A satellite in a low orbit fires its engine briefly to move into a higher circular orbit. Which change happens once it is in the new orbit?', NULL, 2, 'multiple_choice'::answer_type, 'Its kinetic energy is smaller, its potential energy larger and its total energy larger', NULL, false, NULL, false, NULL, 'Higher circular orbit: v is smaller, so Ek = GMm/2r is smaller; Ep = −GMm/r is less negative; total E = −GMm/2r is less negative, i.e. larger (the engine did work). Mark scheme (3 marks). C1: Ek ∝ 1/r. C1: E = −GMm/2r increases. A1: C (Its kinetic energy is smaller, its potential energy larger and its total energy larger).', 3, NULL, NULL),
('31240c26-a258-5ad7-9620-f2fe295561a9', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 44, 44, 'A satellite orbiting just above the Moon''s surface (radius 1.74 × 10⁶ m, g = 1.62 N kg⁻¹) needs what orbital speed? Use v = √(gR).', NULL, 2, 'numeric'::answer_type, '1679', 'm s⁻¹', false, NULL, false, NULL, 'v = √(gR) = √(1.62 × 1.74 × 10⁶) = 1680 m s⁻¹. Mark scheme (3 marks). C1: mg = mv²/R. C1: substitution. A1: v = 1680 m s⁻¹.', 3, NULL, NULL),
('df6d44eb-9ddc-5534-83be-02654ea9d63e', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 45, 45, 'Calculate the minimum number of geostationary satellites needed so that every point on the Equator can see at least one, given that a satellite at radius 4.22 × 10⁷ m can see the Equator over an angle of 2 cos⁻¹(R/r) at the Earth''s centre (R = 6.37 × 10⁶ m). Give the angle in degrees.', NULL, 2, 'numeric'::answer_type, '162.6', '°', false, NULL, false, NULL, 'R/r = 6.37 × 10⁶ ÷ 4.22 × 10⁷ = 0.151. Angle = 2 cos⁻¹ 0.151 = 163°, so 360 ÷ 163 → at least 3 satellites. Mark scheme (4 marks). C1: R/r. C1: inverse cosine. B1: 3 satellites. A1: angle = 163°.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fg8a813659-t fg8a813659-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8a813659-t">Coverage from a geostationary satellite</title><desc id="fg8a813659-d">The Earth and a geostationary orbit of radius 4.22 × 10⁷ m drawn to scale; dashed lines from one satellite touch the Earth, marking the part of the Equator it can see.</desc><circle cx="180" cy="160" r="19" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="180" cy="160" r="126" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="174" y="30" width="12" height="8" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="160" x2="180" y2="34" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><text x="198" y="102" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">4.22 × 10⁷ m</text><line x1="180" y1="34" x2="161.2" y2="157.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="180" y1="34" x2="198.8" y2="157.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/></svg>', 'The Earth and a geostationary orbit of radius 4.22 × 10⁷ m drawn to scale; dashed lines from one satellite touch the Earth, marking the part of the Equator it can see.'),
('27ca2eb7-cead-5e92-91b6-ed14cf18228a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 46, 46, 'A satellite moves in a circular orbit 1200 km above the Earth''s surface. Calculate the gravitational field strength at the orbit and hence the satellite''s centripetal acceleration. Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 2, 'numeric'::answer_type, '6.949', 'm s⁻²', false, NULL, false, NULL, 'r = 6.37 × 10⁶ + 1.2 × 10⁶ = 7.57 × 10⁶ m. a = g = GM/r² = 3.98 × 10¹⁴ ÷ (7.57 × 10⁶)² = 6.95 m s⁻². Mark scheme (3 marks). C1: r = R + h. C1: g = GM/r². B1: centripetal acceleration = g.', 3, NULL, NULL),
('7f374068-933c-558b-992b-e43385ebe40a', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 47, 47, 'A telecommunications company plans a geostationary satellite. (a) State three properties of a geostationary orbit. (b) Use Newton''s law of gravitation and circular motion to derive r³ = GMT²/4π². (c) Calculate the orbital height above the surface. Give only the answer to (c). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '3.578e7', 'm', false, NULL, false, NULL, '(a) Equatorial; period equal to the Earth''s rotation period (≈ 24 h); moving west to east. (b) GMm/r² = mω²r = m(4π²/T²)r, so r³ = GMT²/4π². (c) r = (3.98 × 10¹⁴ × 86164² ÷ (4π²))^(1/3) = 4.21 × 10⁷ m, h = 4.215 × 10⁷ − 6.37 × 10⁶ = 3.58 × 10⁷ m. Mark scheme (6 marks). B1: equatorial. B1: 24 h period and same direction. M1: GMm/r² = mω²r. A1: r³ = GMT²/4π². C1: substitution. A1: h = 3.58 × 10⁷ m.', 6, NULL, NULL),
('e25bcb19-c916-58d9-820e-1c8625f68583', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 48, 48, 'A satellite of mass 1200 kg is moved from a low orbit (radius 6.80 × 10⁶ m) to a geostationary orbit (radius 4.22 × 10⁷ m). (a) Calculate its total orbital energy in each orbit, using E = −GMm/2r. (b) Calculate the energy that must be supplied. Give only the answer to (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '2.947e10', 'J', false, NULL, false, NULL, '(a) E₁ = −3.98 × 10¹⁴ × 1200 ÷ (2 × 6.80 × 10⁶) = −3.51 × 10¹⁰ J. E₂ = −3.98 × 10¹⁴ × 1200 ÷ (2 × 4.22 × 10⁷) = −5.66 × 10⁹ J. (b) ΔE = E₂ − E₁ = −5.662 × 10⁹ − (−3.514 × 10¹⁰) = 2.95 × 10¹⁰ J. Mark scheme (5 marks). C1: E = −GMm/2r. A1: E₁. A1: E₂. C1: ΔE = E₂ − E₁. A1: ΔE = 2.95 × 10¹⁰ J.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fg06bf74ef-t fg06bf74ef-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg06bf74ef-t">Low orbit and geostationary orbit</title><desc id="fg06bf74ef-d">The Earth with a low orbit of radius 6.80 × 10⁶ m and a geostationary orbit of radius 4.22 × 10⁷ m, drawn to scale.</desc><circle cx="180" cy="160" r="19" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="180" cy="160" r="20.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="184.2" y="138.4" width="12" height="8" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="202.2" y="130.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">6.80 × 10⁶ m</text><circle cx="180" cy="160" r="126" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><rect x="185" y="30.5" width="12" height="8" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="203" y="22.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">4.22 × 10⁷ m</text></svg>', 'The Earth with a low orbit of radius 6.80 × 10⁶ m and a geostationary orbit of radius 4.22 × 10⁷ m, drawn to scale.'),
('30225084-200e-518d-8e66-b21b63e93eff', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 49, 49, 'An astronaut on the ISS (orbit radius 6.79 × 10⁶ m) says she feels weightless. (a) Calculate g at the ISS. (b) Express it as a percentage of the surface value (9.81 N kg⁻¹). (c) Calculate the station''s centripetal acceleration from its speed of 7.66 km s⁻¹, and use it to explain the weightlessness. Give only the percentage in (b). Take G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the Earth = 5.97 × 10²⁴ kg and its radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '88.04', '%', false, NULL, false, NULL, '(a) g = GM/r² = 3.98 × 10¹⁴ ÷ (6.79 × 10⁶)² = 8.64 N kg⁻¹. (b) Percentage = 8.64 ÷ 9.81 × 100 = 88.0 %. (c) a = v²/r = 7660² ÷ 6.79 × 10⁶ = 8.64 m s⁻², equal to g: the station and the astronaut fall freely together, so there is no contact force and she feels weightless. Mark scheme (7 marks). C1: g = GM/r². A1: g. A1: percentage. C1: a = v²/r. A1: percentage = 88.0%. B1: free fall together. B1: no contact force.', 7, NULL, NULL),
('7e8b0960-c522-5bca-ac87-a77052f15d00', 'd70c2ad3-65ef-4eb3-a897-6802ce9a60c1', '663cb445-bbf3-4c10-b9c6-b9a0f8be4bbe', 'a-level', '17.7', '9702 coursebook 17.7 · Orbiting the Earth', 50, 50, 'A satellite in a low circular orbit at radius 6.70 × 10⁶ m has a speed of 7.71 km s⁻¹. (a) Calculate its period. (b) An observer on the Equator sees it pass overhead. Explain why the time until it is next overhead is longer than its period, if it orbits in the same direction as the Earth spins. (c) Calculate that time, given that the Earth turns at 7.29 × 10⁻⁵ rad s⁻¹. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '5829', 's', false, NULL, false, NULL, '(a) T = 2πr/v = 2π × 6.70 × 10⁶ ÷ 7710 = 5460 s. (b) The observer is carried round in the same direction, so the satellite must go a little more than one full orbit to catch up. (c) Relative angular speed = v/r − ω_E = 7710 ÷ 6.70 × 10⁶ − 7.29 × 10⁻⁵ = 0.00108 rad s⁻¹, t = 2π ÷ 0.001078 = 5830 s. Mark scheme (5 marks). C1: T = 2πr/v. A1: T. B1: observer moves in the same direction. C1: relative angular speed. A1: t = 5830 s.', 5, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('4be5011d-d006-5add-b647-da79b8a01fe6', '992791db-00eb-5386-82f0-6bb097ea58b5', 'The orbit must be above the Equator', 'A', false, 0),
('a06eb1bb-b43c-5861-b1a8-5f18861fa824', '992791db-00eb-5386-82f0-6bb097ea58b5', 'The period must equal the Earth''s rotation period (about 24 h)', 'B', false, 1),
('92f63b2f-053f-5d3b-944a-9a5315615291', '992791db-00eb-5386-82f0-6bb097ea58b5', 'The satellite must have a mass of exactly 1000 kg', 'C', true, 2),
('8e40c0cf-467d-58cf-9566-617ca811ba2f', '992791db-00eb-5386-82f0-6bb097ea58b5', 'The satellite must move in the same direction as the Earth rotates', 'D', false, 3),
('90a06f46-22e1-5dc2-b29e-1d69ed373d04', 'c0948d15-ecde-5180-b8da-03bdefc454dc', 'They stay above the same point on the Earth, so dishes need not track them', 'A', true, 0),
('a42d0d70-b5ca-5cc3-a9e5-16311f5d8007', 'c0948d15-ecde-5180-b8da-03bdefc454dc', 'They are close to the Earth, giving strong signals', 'B', false, 1),
('117ac56f-fb2a-5eeb-a1f3-e941150cca8f', 'c0948d15-ecde-5180-b8da-03bdefc454dc', 'They pass over the poles, covering the whole Earth', 'C', false, 2),
('b641ef8e-1d13-5f6c-8c7e-af1345d50602', 'c0948d15-ecde-5180-b8da-03bdefc454dc', 'They move faster than the Earth rotates', 'D', false, 3),
('67c3d7c7-c31b-5a04-8ed6-90c4f6b9ee11', '1714bfce-a88a-5975-9e9d-b8a1cc2cccf7', 'It stays above one point on the Equator', 'A', false, 0),
('4c319581-dbba-53ea-872f-27e2f07c0ba9', '1714bfce-a88a-5975-9e9d-b8a1cc2cccf7', 'It is always in sunlight', 'B', false, 1),
('b64032d2-4049-5208-b7d4-dea836209a0f', '1714bfce-a88a-5975-9e9d-b8a1cc2cccf7', 'It never passes over the oceans', 'C', false, 2),
